(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["moe"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-nvfp4-moe-weights"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-1\">一 · 一次长尾专家引发的线上事故</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-2\">二 · 它到底解决哪一个推理问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-3\">三 · 它不解决什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-4\">四 · 机制与代价：为什么边界长这样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-5\">五 · 适用边界的判定条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-6\">六 · 边界与失效：NVFP4 在 MoE 解码里救什么、不救什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-7\">七 · 离线分块：权重落到 NVFP4 的那一刀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-8\">八 · 路由命中：按专家 ID 取 4-bit 权重块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-9\">九 · 激活侧量化：每 token 动态定标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-10\">十 · tcgen05 FP4 MMA：分组 GEMM 与 FP32 累加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-11\">十一 · 反量化写回：尺度乘回去，进入下一层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-12\">十二 · 边界与失效条件：从 block 尺度到专家长尾的代价链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-13\">十三 · 边界条件与系统代价：什么时候 NVFP4 反而更慢</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-14\">十四 · 从舍入式到微缩放：误差上界的推导关键一步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-15\">十五 · 激活侧动态量化：逐 token 缩放与 FP32 累加的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-16\">十六 · 分组 GEMM 的块索引推导：从路由表到 MMA 描述符</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-17\">十七 · 误差累积的逐层推导与 FP8 回退判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-18\">十八 · 元数据带宽账本：block 大小的定量取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-19\">十九 · 微缩放因子的边界：元数据开销与长尾专家误差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-20\">二十 · 请求形态：解码主导、短输入、长输出的会话负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-21\">二十一 · 长度分布：尾部长度决定批大小上限，而非均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-22\">二十二 · 并发与批大小：专家并集大小是隐藏的批约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-23\">二十三 · 负载不对时的三种失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-24\">二十四 · 配方判据：把负载特征映射到量化档位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-25\">二十五 · 容量规划中的负载配方接口</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-26\">二十六 · 硬件档位与算力前提</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-27\">二十七 · 并行拓扑：以驻留量反推专家并行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-28\">二十八 · 量化方案：权重 NVFP4、激活 FP8 与回退清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-29\">二十九 · KV 策略：与专家权重争夺同一块显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-30\">三十 · 调度参数：批大小、容量因子与 piggyback 的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-31\">三十一 · 可复现的配置求解顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-32\">三十二 · 配方落地时的边界：元数据带宽、回退粒度与专家并行域收缩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-33\">三十三 · 显存账：4 bit 省下来的是驻留量，不是峰值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-34\">三十四 · 带宽账：HBM 读取与缩放因子的拉锯</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-35\">三十五 · 通信账：专家并行域缩小与 All-to-All 的二次效应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-36\">三十六 · 功耗与热：算力密度翻倍后的新约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-37\">三十七 · 尾延迟：长尾专家与量化误差的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-38\">三十八 · 四比特专家驻留之后：带宽账本、元数据税与长尾专家的尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-39\">三十九 · 精度漂移的定位：从长尾专家到敏感层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-40\">四十 · OOM 的三条来源与显存账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-41\">四十一 · 批抖动与路由不均的耦合诊断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-42\">四十二 · 尾延迟尖刺的归因路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-43\">四十三 · 监控面与回滚闸门</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-44\">四十四 · 边界条件、失效链与可回滚的监控面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-45\">四十五 · 同族量化的坐标系：三条轴决定选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-46\">四十六 · 决策表：按约束条件落位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-47\">四十七 · 与 FP8 的对照：收益来自哪一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-48\">四十八 · 与整张量统一量化的对照：局部动态范围的价值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-49\">四十九 · 与稀疏量化、投机解码的耦合边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-50\">五十 · 适用条件的硬边界与验收口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-nvfp4-moe-weights-sec-51\">五十一 · 同族算法怎么选：NVFP4 的边界、失效条件与系统代价</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">离线将专家权重按 block 量化到 NVFP4，存缩放因子</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码时按 router 选中的专家加载对应 4-bit 权重块</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">激活按 token 动态量化到 FP8/NVFP4 并附带缩放</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">tcgen05 FP4 MMA 执行分组 GEMM，累加器保持 FP32</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">反量化缩放后写回，进入下一层</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-nvfp4-moe-weights-sec-1\">一 · 一次长尾专家引发的线上事故</h3>\n<p>某线上推理服务在把 MoE 解码链路从 FP8 权重切到 NVFP4 之后，吞吐与显存指标都按预期改善：专家权重驻留量下降，单卡能多放几个专家，跨卡 All-to-All 的频次也随之减少。但上线后监控到一类很难归因的异常——绝大多数请求的 TPOT 与输出质量正常，少数请求却在特定话题上出现明显的语义漂移，输出与输入意图脱节，且复现率随话题长尾程度上升。排查路径最终落在 router 的选择分布上：这些请求被路由到了样本极少的专家，而这些专家的权重在 4-bit 量化后误差累积最严重。事故的本质不是量化格式坏了，而是量化误差在长尾专家上没有被任何机制兜住。</p>\n<p>这个案例精确划出了 NVFP4 权重与激活量化的适用边界：它解决的是显存与带宽受限的 MoE 解码问题，不解决长尾专家的精度保持问题。把这两件事混为一谈，就会得到上面这种“指标全绿、质量局部塌陷”的失败形态。本片段只讨论这个算法的定位与边界，微缩放格式本身的数值细节、路由策略、分组 GEMM 的核实现分别在其他片段展开，此处只用一句话指路。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-2\">二 · 它到底解决哪一个推理问题</h3>\n<p>MoE 的推理成本结构在解码阶段与预填阶段完全不同。预填阶段是算力主导，矩阵乘的算术强度高；解码阶段每步只处理少量 token，却要按 router 的选择把被选中专家的全部权重从 HBM 读进来，算术强度极低，HBM 带宽成为硬瓶颈。专家参数量巨大导致权重显存占用使单卡放不下全部专家，于是要么跨卡 All-to-All 取权重，要么把专家切分到更多卡上，两条路都在放大通信与调度代价。FP8 把权重压到 1 字节，仍然不够：它只把驻留量减半，没有改变“解码每步要搬大量专家权重”这一带宽事实。</p>\n<p>NVFP4 的定位正是同时打这两个点。权重按 block 量化到 4 bit，显存降到 FP16 的 1/4，单卡可容纳更多专家，专家并行域因此可以缩小，跨卡 All-to-All 相应减少；同时 Blackwell 的 tcgen05 原生支持 FP4 MMA，算力密度翻倍，让“读进来的 4-bit 权重”能被高效消费掉，而不是读得快、算得慢。换句话说，它把解码阶段的瓶颈从“搬不动”往“搬得动且算得动”推了一步。</p>\n<div class=\"formula\">$$w_q=\\text{round}\\left(\\frac{w}{s}\\right),\\ s=\\frac{\\max|w_{\\text{block}}|}{\\text{FP4\\_MAX}},\\quad \\text{误差}\\ \\epsilon\\le \\frac{s}{2}\\ \\text{每元素}$$</div>\n<p>上式给出的是单 block 内的误差上界：误差正比于该 block 的缩放因子 s，也就是正比于 block 内的最大绝对值。这个结构决定了它的强项与弱项——动态范围局部集中、分布规整的权重块量化损失小；而长尾专家恰恰是样本少、权重分布未经充分统计的块，s 由少数极端值撑起，其余元素的相对误差被放大。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-3\">三 · 它不解决什么</h3>\n<p>第一，它不解决长尾专家的精度问题。失败模式很明确：长尾专家样本少，4-bit 量化误差在其上累积，可能导致路由到这些专家的 token 输出明显偏移。这不是靠调 block 大小能消掉的，因为误差来源是统计不足而非格式缺陷。工程上的兜底是对量化敏感层回退到 FP8，用一层混合精度把长尾路径保护起来；材料未给出具体精度下降数字，因此不能承诺任何量化收益的数值。</p>\n<p>第二，它不解决缩放因子元数据的读取开销。每个 16 或 32 元素共享一个 E8M0 缩放因子，block 越小，元数据越多，额外读取开销可能抵消 4-bit 权重带来的带宽节省。这意味着“把 block 调到最小以保精度”是一条会反噬吞吐的路：精度收益与带宽代价在同一根轴上反向拉扯，block 尺寸是这条轴上的工作点，不是可以单独优化的参数。</p>\n<p>第三，它不解决激活侧的多层误差叠加。敏感层未回退 FP8 时，FP4 激活量化误差会在多层叠加后放大，破坏生成质量。权重可以离线量化、反复校准，激活是按 token 动态量化的，没有离线校准的机会，因此激活侧的精度策略必须与权重侧分开决策——这也是为什么部署配方里权重用 NVFP4、激活用 FP8 或 NVFP4 是一个可选项而非固定项。</p>\n<p>第四，它不改变调度层的容量约束。batch 大小受专家权重驻留量约束，SLO 以 TPOT 与并发数为目标；4-bit 权重放宽了驻留量上限，但连续批处理、容量因子、令牌丢弃这些调度决策仍在别的片段里处理，量化只是把约束的数值边界往外推，不替代调度本身。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-4\">四 · 机制与代价：为什么边界长这样</h3>\n<p>机制链条是离线与在线两段。离线把专家权重按 block 量化到 NVFP4 并存下缩放因子；在线解码时按 router 选中的专家加载对应 4-bit 权重块，激活按 token 动态量化到 FP8 或 NVFP4 并附带缩放，tcgen05 FP4 MMA 执行分组 GEMM、累加器保持 FP32，反量化缩放后写回进入下一层。核心关系是微缩放量化：</p>\n<div class=\"formula\">$$w\\approx s\\cdot q,\\quad s=2^{e-127},\\quad \\hat{w}=s\\cdot q$$</div>\n<p>其中 q 为 4-bit 量化值，s 为每 16 或 32 个元素共享的 E8M0 缩放因子，e 为指数字段；反量化时 ŵ=s·q 参与 MMA。E8M0 只用指数不用尾数，意味着缩放因子本身是 2 的幂，硬件可以在 MMA 流水里以极低成本完成缩放，这是它能进 tcgen05 的前提。累加器保持 FP32 则是另一条边界：4-bit 乘法的部分积误差不进入累加路径，多层叠加的放大主要来自激活量化而非累加。</p>\n<p>代价可以按三条资源轴拆开。显存轴：权重降到 FP16 的 1/4，收益确定；但缩放因子元数据随 block 变小而增多，净收益是两项之差。带宽轴：解码每步读取的专家权重字节数下降，HBM 压力缓解，但元数据读取与反量化指令占用一部分带宽预算，block 太小时带宽收益被抵消。算力轴：tcgen05 原生 FP4 MMA 使算力密度翻倍，前提是权重与激活都落在 FP4 路径上；一旦敏感层回退 FP8，那部分层就退回 FP8 的算力密度，混合精度图的切分点因此直接影响端到端吞吐。</p>\n<p>一个具体的工程判断：假设某层专家权重在 FP16 下驻留量刚好让单卡放不下全部专家、必须跨卡 All-to-All，切到 NVFP4 后驻留量降到 1/4，专家并行域可以缩小，All-to-All 频次下降——这是收益的主项。但如果该层同时是长尾专家集中的层，4-bit 误差会在这些专家上累积，此时正确动作不是继续压 block 尺寸，而是把这一层整体回退 FP8，接受该层驻留量回到 1/2 的代价，换取长尾路径的稳定。这就是“敏感层回退”在系统层面的真实含义：它不是精度补丁，而是并行拓扑与显存预算的重新分配。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-5\">五 · 适用边界的判定条件</h3>\n<p>把边界写成可判定的条件，比写成“适用于显存受限场景”有用。第一，硬件必须落在支持 tcgen05 原生 FP4 MMA 的 Blackwell 档位；没有原生 FP4 MMA 的硬件上跑 NVFP4 只会得到“权重小了但算得慢”的反效果，收益方向反转。第二，负载必须是显存与带宽受限的 MoE 解码；预填主导或算力主导的负载，量化带来的带宽收益被算力瓶颈掩盖，收益有限。第三，专家分布必须可评估：如果无法识别长尾专家与敏感层，就没有回退 FP8 的落点，事故形态就会像第一节那样在监控盲区里发生。第四，规模上限受量化误差约束——这不是“能压多大就压多大”的算法，长尾专家与敏感层需要回退 FP8，材料未给出具体精度下降数字，因此容量规划必须留出混合精度的显存余量，而不能按纯 4-bit 的理想值做预算。</p>\n<table class=\"mini\"><thead><tr><th>判定项</th><th>满足时</th><th>不满足时</th></tr></thead><tbody><tr><td>硬件档位</td><td>tcgen05 原生 FP4 MMA，算力密度翻倍</td><td>无原生 FP4 MMA，收益方向反转</td></tr><tr><td>负载形态</td><td>显存与带宽受限的 MoE 解码</td><td>算力主导，带宽收益被掩盖</td></tr><tr><td>专家分布</td><td>可识别长尾专家与敏感层，有 FP8 回退落点</td><td>无回退落点，误差在盲区累积</td></tr><tr><td>block 尺寸</td><td>元数据开销小于权重带宽节省</td><td>block 太小，带宽收益被抵消</td></tr></tbody></table>\n<p>这张表的作用是把“能不能用”变成“在什么条件下用、用在哪一层”。事故案例里的服务满足了前两条却不满足第三条，于是量化收益兑现了、质量边界失守了。NVFP4 权重与激活量化的正确用法，是在满足硬件与负载条件的前提下，用敏感层回退 FP8 把长尾路径圈出来，再让 4-bit 路径承担其余层的显存与带宽收益——收益与兜底必须成对部署，单独部署任何一半都会得到上面那种局部塌陷的失败形态。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-6\">六 · 边界与失效：NVFP4 在 MoE 解码里救什么、不救什么</h3>\n<p>一次典型的线上事故足以说明这个方案的靶心在哪：某 MoE 推理服务在扩容后仍频繁触发 TPOT 超时，排查发现单卡放不下全部专家，router 每次选中远端专家都要走跨卡 All-to-All，解码阶段每 token 的专家权重读取把 HBM 带宽吃满，而 FP8 权重已经压到 8 bit 仍不够——显存与带宽是双重瓶颈，不是算力瓶颈。NVFP4 针对的正是这个组合：离线把专家权重按 block 量化到 4 bit 并存储每 16 或 32 个元素共享的 E8M0 缩放因子，解码时按 router 选中的专家只加载对应 4-bit 权重块，激活按 token 动态量化到 FP8 或 NVFP4 并附带缩放，tcgen05 原生 FP4 MMA 执行分组 GEMM、累加器保持 FP32，反量化缩放后写回进入下一层。它不解决的是算力富余但访存模式病态的场景（如专家命中极度倾斜导致的负载不均），也不解决精度本身已逼近下限的模型——4 bit 不是无损压缩。</p>\n<p>量化误差的边界由微缩放格式本身决定：$$w\\approx s\\cdot q,\\quad s=2^{e-127}$$，其中 $q$ 为 4-bit 量化值、$s$ 为每 16 或 32 个元素共享的 E8M0 缩放因子、$e$ 为指数字段，反量化时 $\\hat{w}=s\\cdot q$ 参与 MMA。误差上界为 $\\epsilon\\le s/2$ 每元素，因此 block 内动态范围越大、$s$ 越大，绝对误差越大。长尾专家样本少，4-bit 量化误差在其上累积，路由到这些专家的 token 输出会明显偏移——这是最典型的失效条件，且材料未给出具体精度下降数字，只能定性判断。工程上的对策是敏感层回退 FP8，把误差从 4-bit 档拉回 8-bit 档，代价是这部分层失去 1/4 显存收益与 FP4 算力密度。</p>\n<p>第二个失效条件是元数据开销反噬带宽收益。缩放因子随 block 变小而增多，每 16 元素一个 E8M0 因子意味着权重之外还要读 1/16 的元数据字节；block 太小时额外读取开销可能抵消 4-bit 权重带来的带宽节省，解码阶段的 HBM 有效载荷反而下降。这与“专家权重显存降到 FP16 的 1/4、单卡容纳更多专家、缩小专家并行域”的收益形成对冲：并行域缩小减少 All-to-All，但元数据读取增加单卡带宽压力。第三个失效条件是激活侧未回退：FP4 激活量化误差会在多层叠加后放大，破坏生成质量，因此激活保持 FP8 或按 token 动态选档是稳定性的必要条件。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>NVFP4 适用</th><th>失效/需回退</th></tr></thead><tbody><tr><td>显存与 HBM 带宽受限的 MoE 解码</td><td>权重 NVFP4、激活 FP8/NVFP4、FP32 累加</td><td>算力富余但专家命中倾斜</td></tr><tr><td>专家权重驻留量约束 batch 与并发</td><td>单卡容纳更多专家，缩小 EP 域</td><td>block 过小，元数据抵消带宽收益</td></tr><tr><td>长尾专家与敏感层</td><td>主体 4-bit，局部回退 FP8</td><td>未回退时误差累积、输出偏移</td></tr></tbody></table>\n<p>系统代价要按解码路径算清：权重显存降到 FP16 的 1/4 直接抬高单卡可驻留专家数，batch 上限随专家驻留量放宽，TPOT 与并发数的 SLO 才有腾挪空间；tcgen05 原生 FP4 MMA 使算力密度翻倍，但解码阶段真正的瓶颈是 HBM 读取而非 MMA 吞吐，因此收益主要来自“少读字节”而非“多算”。判断是否上 NVFP4 的工程准则是：先确认瓶颈在专家权重读取带宽与显存驻留，再确认长尾专家占比与敏感层清单可枚举、可回退；两者缺一，4-bit 的收益会被精度修复或元数据开销吃掉。</p>\n<h3 id=\"alg-nvfp4-moe-weights-sec-7\">七 · 离线分块：权重落到 NVFP4 的那一刀</h3>\n<p>机制的第一步发生在任何请求到达之前。对每个专家权重张量，按 16 或 32 个元素切一个 block，块内取绝对最大值定缩放因子，再把每个元素四舍五入到 4-bit 码点。这一步的输入是 FP16/BF16 专家权重，输出是两块东西：4-bit 权重码点数组，以及与之同形的 E8M0 缩放因子数组（每 block 一个字节量级）。代价落在显存与离线算力上，不落在在线延迟上——但它决定了在线阶段的一切：权重显存降到 FP16 的 1/4，单卡能驻留的专家数随之上升，专家并行域可以收窄，跨卡 All-to-All 的流量跟着下降。</p>\n<p>量化公式本身是块局部的：</p>\n<div class=\"formula\">$$w_q=\\text{round}\\left(\\frac{w}{s}\\right),\\quad s=\\frac{\\max|w_{\\text{block}}|}{\\text{FP4\\_MAX}},\\quad \\epsilon\\le \\frac{s}{2}\\ \\text{每元素}$$</div>\n<p>关键在于 $s$ 是每 block 独立的，而不是整张量共享。整张量统一量化会让动态范围小的 block 被大 block 的尺度压死，微缩放正是用元数据换局部精度。工程判断在这里出现分岔：block 取 32 时元数据占比低、读取放大可控；取 16 时局部动态范围保留更好、长尾专家误差更小，但缩放因子数组膨胀，解码时每读一段权重就要多读一段因子。这个取舍要在离线阶段按层定，而不是全局一刀切。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-8\">八 · 路由命中：按专家 ID 取 4-bit 权重块</h3>\n<p>请求进入解码循环后，第一个在线步骤是 router 给出每个 token 的专家选择。此处的输入是 token 的隐状态，输出是若干专家 ID 及权重系数。对本片段而言，路由的语义只有一个：它把“要读哪些权重块”变成了一次索引。解码阶段每 token 每层要读的权重字节数，直接由被选中专家的 NVFP4 块大小乘以专家数决定，这就是 HBM 带宽成为瓶颈的根源——算术强度极低，读权重的时间远大于算的时间。</p>\n<p>取块的代价要拆成两笔账。第一笔是权重本身：4-bit 让同样多的专家权重只占 FP16 的 1/4 字节数，带宽压力按比例下降。第二笔是元数据：每个 block 附带一个 E8M0 因子，block 越小因子越密。设 block 大小为 $B$、每元素 4 bit，则每元素平均读取位数为 $4+8/B$；当 $B=32$ 时约 4.25 bit，$B=16$ 时约 4.5 bit。这个式子说明缩放因子的开销是有界的，但它在小 block 加长尾专家稀疏命中时会放大：命中的块少、因子照读，收益被抵消。因此取块逻辑必须与专家驻留布局对齐——专家权重在显存中按块连续排布，因子紧随其后，一次大粒度读取把码点与因子一起拉进片上，避免两次访存。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-9\">九 · 激活侧量化：每 token 动态定标</h3>\n<p>权重是离线定标的，激活不能。每个 token 的隐状态分布随输入变化，必须在进入 MMA 前动态量化。输入是该层激活张量，输出是 FP8 或 NVFP4 码点加对应的缩放因子，粒度按 token 或按 token 内的 block。这一步的代价是片上算力与一次额外的读写回合：量化核要扫一遍激活求尺度、做缩放与舍入，再写回供 MMA 消费。它不占 HBM 带宽的大头，但在小 batch 解码时相对固定开销不可忽略，因此实现上倾向把激活量化融进前一个算子的尾声，而不是独立起一个 kernel。</p>\n<p>激活精度档位的选择是稳定性技巧的落点。权重压到 4-bit 后，若激活也压到 NVFP4，两层误差会在多层叠加后放大；对量化敏感层把激活留在 FP8、权重留在 NVFP4 的混合配置，是抑制这种放大的常规手段。失败模式很明确：敏感层未回退 FP8 时，FP4 激活量化误差逐层累积，破坏生成质量。这里的工程判断是“按层分档”，而不是按模型统一。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-10\">十 · tcgen05 FP4 MMA：分组 GEMM 与 FP32 累加</h3>\n<p>码点与因子就位后进入计算步。输入是 A 侧的激活码点与尺度、B 侧的专家权重码点与尺度，输出是 FP32 累加结果。tcgen05 原生支持 FP4 MMA，算力密度相对 FP8 翻倍，这是把 4-bit 从“省显存”变成“也省时间”的前提。累加器保持 FP32 是硬约束：4-bit 乘 4-bit 的乘积动态范围窄，但跨 K 维累加若用低精度会迅速丢有效位，FP32 累加让块级缩放的反量化误差不进入累加链。</p>\n<p>分组 GEMM 的形态由路由决定：同一 token 的不同专家、同一专家的不同 token 被聚成组，按组发起 MMA。伪代码思路是：对每个专家组，取该组激活块与权重块，按 $s_a\\cdot s_w$ 组合尺度送入 MMA，累加至 FP32 分片；组间不共享累加器。代价在调度侧：组越小、组数越多，MMA 的启动与收尾开销占比越高，TMEM 与寄存器分片的利用率越难打满。因此分组粒度要与 batch 大小匹配——batch 大时组自然变粗，batch 小时要靠融合大核把多个小组合并处理，这一点与解码融合核的设计直接相关。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-11\">十一 · 反量化写回：尺度乘回去，进入下一层</h3>\n<p>MMA 输出的是“以码点为单位”的累加值，必须乘回尺度才是真实数值。输入是 FP32 累加分片与两级尺度，输出是本层输出激活，随后进入下一层。反量化的代价主要不在算力，而在数据通路：FP32 累加结果要经 TMEM 读出、乘尺度、转回目标精度、写回片上或显存，这一串动作在每层每 token 上重复。若把尺度乘法放在写回路径上批量做，可以摊薄开销；若逐元素散做，延迟会被放大。</p>\n<p>这一步也是误差账目的结算点。块级量化误差 $\\epsilon\\le s/2$ 每元素，经 $s_a\\cdot s_w$ 组合后进入输出；长尾专家样本少，4-bit 量化误差在其上累积更明显，路由到这些专家的 token 输出会偏移。工程上的对冲是两条：离线阶段对长尾专家与敏感层回退 FP8，在线阶段靠 FP32 累加与按层分档把误差挡在可控范围内。材料未给出具体精度下降数字，因此容量规划只能按“回退比例”做保守估计——回退层越多，显存收益越接近 FP8 档位，专家驻留数与并行域收窄的幅度都要相应打折。</p>\n<p>把五步串起来看，代价的重心在第二、四步：取块的 HBM 带宽与分组 GEMM 的调度效率。前者由 block 大小与专家布局决定，后者由 batch 与分组粒度决定。一个可执行的判断是：先按 TPOT 与并发数定 SLO，再由专家驻留量反推可用的 block 大小与回退层比例，最后才决定专家并行域——顺序反过来，就会在带宽与精度之间反复返工。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-12\">十二 · 边界与失效条件：从 block 尺度到专家长尾的代价链</h3>\n<p>微缩放格式的精度边界由 block 尺度直接决定。反量化时 $\\hat{w}=s\\cdot q$ 参与 MMA，而 $s=2^{e-127}$ 是每 16 或 32 个元素共享的 E8M0 因子，因此单个 block 内的相对误差被 $\\max|w_{\\text{block}}|$ 锁定：block 内若混入一个大幅值离群元素，其余元素的有效位数被整体压低，误差按 $\\epsilon\\le s/2$ 逐元素累积。这条边界在 MoE 上尤其危险——长尾专家样本少，其权重分布未被充分约束，量化后偏差不会在训练式微调中被纠正，只能原样进入推理。路由到这些专家的 token 输出偏移，且偏移随层数叠加；工程上必须把敏感层（通常是首尾若干层与归一化邻近的投影）回退到 FP8，代价是这部分权重失去 1/4 显存收益，混合精度布局也让权重加载路径出现两条分支，加载器需按层标签选择 4-bit 或 8-bit 描述符，增加一次元数据判定。</p>\n<p>第二个失效点是缩放因子的元数据税。每 16 元素一个 E8M0 因子意味着每 16 个 4-bit 权重（8 字节）附带 1 字节缩放，元数据占权重字节的 12.5%；若 block 缩到 8 元素，该比例翻倍，HBM 实际读取量上升，4-bit 的带宽节省被部分抵消。解码阶段按 router 选中的专家加载权重块时，读取粒度是 block 而非张量，因此有效带宽为</p>\n<div class=\"formula\">$$B_{\\text{eff}}=\\frac{N_w\\cdot 0.5\\ \\text{B}+N_w/b\\ \\text{B}}{N_w\\cdot 0.5\\ \\text{B}}\\cdot B_{\\text{HBM}}$$</div>\n<p>其中 $N_w$ 为元素数、$b$ 为 block 大小。$b=32$ 时开销约 6%，$b=16$ 时约 12.5%，$b=8$ 时约 25%——block 越小，局部动态范围保留越好但带宽收益越薄，这是一个必须按专家分布实测选定的折中点，而非固定配置。</p>\n<p>第三个代价在激活侧与累加路径。激活按 token 动态量化到 FP8 或 NVFP4 并附带缩放，量化本身要在 MMA 之前完成一次归约求 $\\max$，对每个 token 是一段短的 reduction 延迟；tcgen05 FP4 MMA 的累加器保持 FP32，写回时再做 $s\\cdot q$ 反量化，因此每个分组 GEMM 的输出都要经过一次缩放乘加，这部分算力不体现在 MMA 峰值里。系统层面的表现是：显存受限的解码场景下 batch 受专家权重驻留量约束，权重压到 4 bit 后单卡可容纳更多专家、专家并行域缩小、跨卡 All-to-All 减少，但若长尾专家回退 FP8 的比例偏高，驻留量优势被侵蚀，TPOT 的收益随之收窄。判断是否启用 NVFP4 的工程准则应落在两处：单卡专家驻留量是否因 4-bit 而跨过“全部专家本地化”的门槛，以及回退 FP8 的层占比是否低到不破坏该门槛；任一不满足，FP8 方案在稳定性上更划算。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-13\">十三 · 边界条件与系统代价：什么时候 NVFP4 反而更慢</h3>\n<p>微缩放量化的收益不是无条件的，它由两个互相拉扯的量决定：权重字节数与缩放因子元数据字节数。设 block 大小为 <i>B</i>，每元素权重占 4 bit，则每元素平均读取字节为 <span class=\"formula\">$$b_{\\text{eff}}=\\frac{4}{8}+\\frac{1}{B}\\ \\text{(字节/元素)}$$</span>其中第二项是 E8M0 缩放因子的摊薄成本。当 <i>B</i>=16 时有效位宽约 4.5 bit，<i>B</i>=32 时约 4.25 bit；若把 block 缩到 8 甚至更小以追求更细的局部动态范围，元数据开销迅速吃掉 4-bit 权重相对 FP8 的带宽节省。解码阶段专家权重读取是 HBM 带宽瓶颈，这条公式直接决定 TPOT：元数据读取与权重读取共享同一带宽预算，block 太小则收益被抵消，这正是该方案最容易被误用的边界。</p>\n<p>第二个边界是误差在长尾专家上的累积。按 <span class=\"formula\">$$\\epsilon\\le \\frac{s}{2},\\quad s=\\frac{\\max|w_{\\text{block}}|}{\\text{FP4\\_MAX}}$$</span>，量化步长由 block 内最大绝对值决定；长尾专家样本稀少，其权重分布未被充分校准，block 内极值偏大时整块步长被抬高，绝大多数元素落在粗网格上，误差随层数叠加后使路由到这些专家的 token 输出明显偏移。工程上的判据是：对路由频次低的专家与数值敏感层（如首尾层、归一化邻近的投影）保留 FP8 副本，形成混合精度专家池，代价是这部分权重失去 1/4 的显存收益，并让加载逻辑多一次分支判断。</p>\n<p>第三是激活侧动态量化的时序代价。激活按 token 量化到 FP8 或 NVFP4 需要在 MMA 之前完成归约求最大值与缩放，这一步落在关键路径上，与权重加载不能完全重叠；若敏感层未回退 FP8，FP4 激活误差会在多层叠加后放大。tcgen05 FP4 MMA 虽把算力密度翻倍、累加器保持 FP32，但分组 GEMM 的粒度受 router 选中专家数约束，专家被切得过散时单次 MMA 的 M 维过小，算力密度优势无法兑现。因此部署配方应把 batch 与专家驻留量绑定：权重压到 4 bit 后单卡容纳更多专家、缩小专家并行域、减少跨卡 All-to-All，但并发数仍受专家权重驻留量约束，SLO 需以 TPOT 与并发数共同定标，而非只看单卡显存占用。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>直接代价</th><th>工程对策</th></tr></thead><tbody><tr><td>block 过小</td><td>元数据带宽抵消权重节省</td><td>block 保持 16/32，按层实测有效位宽</td></tr><tr><td>长尾专家误差累积</td><td>token 输出偏移</td><td>低频专家回退 FP8</td></tr><tr><td>敏感层 FP4 激活</td><td>多层误差放大</td><td>激活侧保留 FP8</td></tr><tr><td>专家切分过散</td><td>MMA M 维不足，算力密度落空</td><td>约束每卡专家数与 batch 配比</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-moe-weights-sec-14\">十四 · 从舍入式到微缩放：误差上界的推导关键一步</h3>\n<p>先把最朴素的定点思路摆出来，再说明为什么它在 MoE 专家权重上不成立。若对整块权重取单一缩放因子 $s=\\max|w|/\\text{FP4\\_MAX}$，则每个元素的量化误差满足 $\\epsilon\\le s/2$。这个上界看似温和，问题出在 $s$ 由块内绝对值最大的元素决定：MoE 专家权重分布长尾极重，少数大幅值元素把 $s$ 抬高，绝大多数小幅值元素被迫落入同一个粗网格，相对误差被放大到不可接受。推导的关键一步在于把“全局最大”换成“块内最大”：把权重沿输入维度切成 $B$ 个元素的块（$B=16$ 或 $32$），每块独立计算 $s_b=\\max|w_{\\text{block}}|/\\text{FP4\\_MAX}$，则每元素误差上界收缩为 $\\epsilon_b\\le s_b/2$。由于 $s_b\\ll s$，误差随块内动态范围而非整张量动态范围缩放——这正是微缩放（microscaling）相对整张量量化的全部收益来源，也是“按 block 共享 E8M0 缩放因子、保留局部动态范围”这句话的数学内容。</p>\n<p>关键的一步不是切块本身，而是把缩放因子限制为 2 的幂。若 $s$ 取任意实数，反量化需要一次真正的乘法；若强制 $s=2^{e-127}$（E8M0 只存指数、不存尾数），则反量化退化为指数加法，硬件可以在 MMA 的数据通路上以移位完成，不占用通用乘法器。代价是 $s$ 只能取离散档位，块内最大元素无法被精确映射到 FP4 的最大可表示值，实际有效误差略高于 $s_b/2$，但换来的是缩放因子与 FP4 尾数可以打包进同一读取事务，且 tcgen05 的 FP4 MMA 能直接消费这一格式。这就是为什么公式写成 $w\\approx s\\cdot q,\\ s=2^{e-127}$，而不是写成任意浮点缩放。</p>\n<div class=\"formula\">$$w_q=\\text{round}\\left(\\frac{w}{s_b}\\right),\\quad s_b=2^{\\,\\lceil \\log_2(\\max|w_{\\text{block}}|/\\text{FP4\\_MAX})\\rceil-127},\\quad \\hat{w}=s_b\\cdot w_q$$</div>\n<p>工程代价落在元数据上。以 $B=16$ 计，每 16 个 4-bit 权重（8 字节）配 1 字节 E8M0，元数据开销为 12.5%；$B=32$ 时降到 6.25%。解码阶段读一个专家的权重块，实际字节数为 $N_w\\cdot(4+8/B)/8$。当 $B$ 缩小到 8 以下，元数据占比超过权重本体的一半，HBM 带宽收益被抵消——这就是“block 太小时带宽收益被抵消”的定量来源，而不是定性担忧。举例：一个 4096×4096 的专家矩阵，FP16 下为 32 MiB；NVFP4 且 $B=16$ 时约 9 MiB，单卡可驻留的专家数随之提升，跨卡 All-to-All 的专家并行域得以收窄。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-15\">十五 · 激活侧动态量化：逐 token 缩放与 FP32 累加的耦合</h3>\n<p>权重离线量化，激活必须在线量化，因为激活值随 token 变化，无法预知动态范围。对每个 token 的激活向量 $x$，取其绝对值最大元素定标：$s_x=\\max|x|/\\text{FP4\\_MAX}$（或 FP8 的对应上限），得到 $x_q=\\text{round}(x/s_x)$。这里有一个容易被忽略的推导要点：MMA 计算的是 $\\sum_i \\hat{w}_i\\hat{x}_i=\\sum_i (s_{w,i}q_{w,i})(s_{x}q_{x,i})$。若权重块缩放 $s_{w,i}$ 随 $i$ 变化而激活缩放 $s_x$ 对整个 token 恒定，则 $s_x$ 可以提到求和号外，块内只需处理 $s_{w,i}$ 的差异；反之若激活也按块缩放，求和号内出现两个变化的缩放因子，反量化必须逐块进行，累加器无法保持单一的 FP32 累加链。这就是“激活按 token 动态量化、权重按 block 静态量化”这一非对称设计的推导依据——它让 tcgen05 的 FP32 累加器在整条 K 维上连续累加，只在写回时做一次缩放。</p>\n<p>伪代码落到可实现层面，核心是把缩放因子的提取与 MMA 的发射解耦：</p>\n<ul>\n<li>离线：对每个专家权重矩阵按 $B$ 切块，求 $s_b$ 并量化为 4-bit，缩放因子按块序紧凑存放，与权重块交错布局以便单次加载覆盖两者。</li>\n<li>解码：router 给出选中专家集合后，按专家 id 取权重块与缩放因子；对当前 batch 的激活逐 token 求 $s_x$，量化为 FP8 或 NVFP4。</li>\n<li>MMA：以分组 GEMM 形式发射 tcgen05 FP4 MMA，K 维按块推进，累加器驻留 TMEM 并保持 FP32；每个块的 $s_{w,i}$ 在累加前不参与，留待写回。</li>\n<li>写回：$\\hat{y}=s_x\\cdot\\sum_i s_{w,i}\\cdot(\\text{块部分和})$，块部分和已在 FP32 累加器中，写回时按块乘 $s_{w,i}$ 再求和，最后乘 $s_x$ 写回输出。</li>\n</ul>\n<p>代价分析：逐 token 求最大值需要一次归约，在长序列预填时是带宽友好的（激活本身要读），但在解码阶段每步只有少量 token，归约的固定开销相对突出，通常与路由计算重叠。累加器保持 FP32 意味着 TMEM 占用按 FP32 计，而非按 4-bit 压缩后的比例——这是显存与带宽账本上必须单列的一项，不能把权重压缩比直接套到累加器上。举例：batch 内 64 个 token、每 token 路由到 2 个专家、隐藏维 7168，则单层激活量化需处理 64×7168 个元素，而归约只需每 token 一次，开销被摊薄在 MMA 主循环之外。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-16\">十六 · 分组 GEMM 的块索引推导：从路由表到 MMA 描述符</h3>\n<p>MoE 解码的 GEMM 不是规整矩阵乘，而是按 token 分组、每组对应一个专家的批处理。推导的关键是把“哪些 token 属于哪个专家”转成 MMA 可消费的块索引。设路由结果为 $(t_j, e_j)$ 对，按专家排序后得到每个专家的 token 段 $[o_e, o_e+n_e)$，则第 $e$ 个专家的计算是 $Y[o_e:o_e+n_e] = X[o_e:o_e+n_e]\\cdot W_e^\\top$。对 tcgen05 而言，需要为每个专家段构造一组 MMA 描述符：A 操作数是激活的 token 段（行偏移 $o_e$，列偏移 0），B 操作数是该专家的 4-bit 权重块（按 K 维切块，每块携带 $s_{w}$）。由于 $n_e$ 随路由变化，段长度不齐，硬件按最大段长发射、以谓词屏蔽越界行，或在段足够大时合并相邻同专家段以减少发射次数。</p>\n<div class=\"formula\">$$\\text{desc}_e=\\big(o_e,\\ n_e,\\ \\text{ptr}(W_e),\\ \\{s_{w,e,k}\\}_{k=1}^{K/B}\\big),\\quad Y[o_e:o_e+n_e]=\\sum_{k}\\big(s_{x}\\cdot s_{w,e,k}\\big)\\cdot Q_X^{(k)}Q_{W_e}^{(k)\\top}$$</div>\n<p>这里有一个实现上的取舍：缩放因子若按 K 维块序存放，MMA 主循环每推进一个 K 块就要取一次 $s_{w,e,k}$，元数据读取与权重读取同频。若把 $s_w$ 预先折叠进激活侧（即对每个 token-专家对预乘 $s_x\\cdot s_{w,e,k}$），则主循环内不再需要元数据，但预乘本身要对每个 K 块做一次标量乘，且折叠后的激活不再是原始 FP8，失去跨专家复用。工程判断是：K 较大时折叠的标量乘开销可忽略且换来主循环零元数据，K 较小时保留逐块缩放更省。代价体现在发射密度上——段长 $n_e$ 很小时（长尾专家只被少数 token 选中），MMA 的利用率随 $n_e$ 下降，这正是长尾专家在系统层面的第二个代价，与量化误差无关。</p>\n<p>举例：一个 batch 内 512 个 token 路由到 8 个专家，若分布均匀则每段 64 行，MMA 的 M 维利用率良好；若某长尾专家只分到 3 个 token，该段的 MMA 几乎空转，但权重块仍要被完整读入——带宽被消耗在利用率极低的段上。这解释了为什么容量因子与令牌丢弃、专家选择路由要在调度层配合，而本层只能通过合并与谓词屏蔽减小损失。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-17\">十七 · 误差累积的逐层推导与 FP8 回退判据</h3>\n<p>单层误差上界 $\\epsilon_b\\le s_b/2$ 只是起点，真正决定生成质量的是多层叠加。设第 $l$ 层输出误差为 $\\delta_l$，量化引入的扰动为 $\\Delta_l$，若层间 Jacobian 的谱范数为 $\\|J_l\\|$，则 $\\|\\delta_{l+1}\\|\\le\\|J_l\\|\\|\\delta_l\\|+\\|\\Delta_l\\|$。当 $\\|J_l\\|&gt;1$ 时误差被放大，敏感层（如注意力输出投影、路由打分前的隐状态）正是 $\\|J_l\\|$ 偏大的位置。长尾专家的问题在于其权重块内动态范围更极端，$s_b$ 被少数大幅值元素抬高，$\\Delta_l$ 更大，而它只服务少量 token，缺乏统计意义上的抵消，于是路由到这些专家的 token 输出偏移明显。这不是定性担忧，而是上述递推的直接结论：误差项同时被 $\\|J_l\\|$ 和偏大的 $s_b$ 放大。</p>\n<p>回退判据应可计算而非凭经验。一个可实现的判据是逐层估计 $\\|\\Delta_l\\|/\\|y_l\\|$：离线量化后，用一小批校准激活跑一遍，比较 FP4 与 FP8 两条路径的输出相对偏差，超过阈值的层标记为敏感层并回退 FP8。伪代码思路：</p>\n<ul>\n<li>对每层 $l$：以校准激活计算 $y^{\\text{FP8}}_l$ 与 $y^{\\text{FP4}}_l$，求 $\\rho_l=\\|y^{\\text{FP4}}_l-y^{\\text{FP8}}_l\\|/\\|y^{\\text{FP8}}_l\\|$。</li>\n<li>若 $\\rho_l&gt;\\tau$，该层权重与激活均走 FP8；否则走 NVFP4。</li>\n<li>对长尾专家单独统计：若某专家被选中的 token 数低于阈值且 $\\rho$ 偏高，仅对该专家回退，而非整层回退。</li>\n</ul>\n<p>代价是混合精度带来的发射分支：同一层内 FP4 与 FP8 两条 MMA 路径并存，TMEM 分配与描述符构造要按两条路径分别准备，调度器需按专家粒度分派。收益是显存账本上只有少数层/专家退回 FP8，整体仍接近 4-bit 的驻留量。举例：若某 MoE 层 64 个专家中有 4 个长尾专家回退 FP8，则该层权重显存约为纯 NVFP4 的 1.06 倍，而避免了这 4 个专家上误差累积导致的输出偏移——这个比例说明回退的粒度应到专家级而非层级的理由。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-18\">十八 · 元数据带宽账本：block 大小的定量取舍</h3>\n<p>把前四节的代价合并成一张可核对的账本。解码阶段读一个专家权重的有效字节数为 $N_w\\cdot(4+8/B)/8$，其中 $4$ 是 FP4 尾数位、$8/B$ 是每元素摊到的 E8M0 位数。相对 FP16 的压缩比为 $16\\big/\\big(4+8/B\\big)$：$B=16$ 时为 $16/4.5\\approx3.56$ 倍，$B=32$ 时为 $16/4.25\\approx3.76$ 倍，$B=8$ 时降为 $16/5=3.2$ 倍。可见 $B$ 从 32 缩到 16 只损失约 5% 的压缩比，从 16 缩到 8 再损失约 10%，且块内动态范围随 $B$ 减小而收窄、误差上界下降。取舍点在于：误差收益随 $B$ 减小是线性的，带宽收益的损失在 $B\\ge16$ 区间很小，到 $B&lt;8$ 才显著。因此 $B=16$ 是误差与带宽的折中点，$B=32$ 适合动态范围本就温和的层。</p>\n<table class=\"mini\"><thead><tr><th>block 大小 $B$</th><th>每元素位数</th><th>相对 FP16 压缩比</th><th>元数据占读取字节比例</th><th>误差上界趋势</th></tr></thead><tbody><tr><td>8</td><td>5.0</td><td>3.2×</td><td>20%</td><td>最小</td></tr><tr><td>16</td><td>4.5</td><td>3.56×</td><td>12.5%</td><td>较小</td></tr><tr><td>32</td><td>4.25</td><td>3.76×</td><td>6.25%</td><td>偏大</td></tr></tbody></table>\n<p>这张表只算权重侧，不含激活与累加器。累加器按 FP32 驻留 TMEM，其占用与 $B$ 无关；激活侧按 token 缩放，元数据为每 token 一个标量，相对激活本体可忽略。真正被 $B$ 影响的是权重读取事务的粒度：若 $B=16$，一个 128 字节的读取事务恰好覆盖 256 个 4-bit 权重加 16 字节缩放因子，与 HBM 的突发长度对齐；若 $B$ 取非 2 的幂，事务边界错位会导致额外读取。这是把 $B$ 限定为 16 或 32 的硬件理由，而非仅仅出于误差考虑。</p>\n<p>失败模式的定量形态在此清晰：长尾专家样本少，$\\Delta_l$ 无统计抵消，输出偏移；元数据随 $B$ 变小而增多，$B&lt;8$ 时读取开销抵消 4-bit 收益；敏感层未回退时 $\\|J_l\\|$ 放大 FP4 激活误差。三者分别对应误差项、带宽项、累积项，工程上应分别用专家级回退、$B\\ge16$ 约束、层间 $\\rho_l$ 判据来封堵，而不是用单一手段处理全部。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-19\">十九 · 微缩放因子的边界：元数据开销与长尾专家误差</h3>\n<p>NVFP4 的收益并非无条件成立，它被两个量同时夹住：每 block 共享一个 E8M0 缩放因子带来的元数据读取，以及 4-bit 尾数在长尾专家上的误差累积。设 block 大小为 <span>B</span>、权重位宽 4 bit，则每元素有效位宽为 <span>4 + 8/B</span>；当 <span>B=16</span> 时元数据已占 50% 的额外位宽，实际有效位宽为 4.5 bit，<span>B=32</span> 时降到 4.25 bit。若把 block 继续缩小以贴合局部动态范围，缩放因子数组本身在 HBM 上的读取量按 <span>1/B</span> 增长，解码阶段本已紧张的带宽会被元数据重新吃掉一部分——收益曲线在某个 <span>B</span> 处出现拐点，而不是单调变好。工程上应把缩放因子与权重块打包成连续布局，让一次 128B 事务同时取到两者，避免两路独立流。</p>\n<div class=\"formula\">$$\\text{有效位宽}=4+\\frac{8}{B},\\quad \\text{元数据流量}\\propto \\frac{N_{\\text{elem}}}{B}$$</div>\n<p>误差侧的失效条件更隐蔽。逐元素误差上界 <span>ε ≤ s/2</span> 只在 block 内最大值被充分采样时才有意义；长尾专家在训练中见到的 token 极少，其权重分布尾部稀疏，<span>max|w_block|</span> 由少数离群值主导，导致同 block 内其余元素被压到极低的有效精度，量化噪声相对这些元素显著放大。路由到这些专家的 token 输出因此偏移，且偏移会随层数叠加。判定是否回退 FP8 的可操作信号是：按专家统计量化前后分组 GEMM 输出的相对偏差，超过阈值的专家整块保留 FP8 副本，而不是逐层试探。</p>\n<p>系统代价落在三处：显存上，FP8 回退副本与 NVFP4 主副本并存，抵消部分 1/4 的节省，需按回退比例重算单卡专家驻留量；带宽上，元数据与回退专家的混合读取使解码 TPOT 的方差变大，SLO 规划要按最坏路径而非均值；算力上，tcgen05 FP4 MMA 与 FP8 路径混跑会打断分组 GEMM 的流水，累加器虽保持 FP32，但切换精度档位带来的同步开销不可忽略。因此回退粒度应选在专家级而非层内算子级，让一个专家的所有 GEMM 走同一精度路径。一个具体例子：某 MoE 层 64 个专家中若 6 个长尾专家回退 FP8，该层权重显存约为纯 NVFP4 的 1.09 倍，但仍远低于全 FP8，且 All-to-All 域因剩余专家仍驻留单卡而不扩大。</p>\n<h3 id=\"alg-nvfp4-moe-weights-sec-20\">二十 · 请求形态：解码主导、短输入、长输出的会话负载</h3>\n<p>NVFP4 权重与激活的负载配方，第一条判据是请求的形态分布，而不是平均长度。这套格式的收益全部来自解码阶段反复读取专家权重的带宽节省：预填阶段的计算密度高、算术强度大，权重读取被摊薄，4-bit 带来的带宽收益远不如解码阶段显著；而解码阶段每生成一个 token 就要把 router 选中的专家权重从 HBM 搬到 SM，算术强度接近 1，HBM 带宽就是唯一瓶颈。因此负载配方要问的是：解码 token 数占总 token 数的比例有多高。</p>\n<p>用公式刻画这个比例。设请求的输入长度为 $L_{\\text{in}}$、输出长度为 $L_{\\text{out}}$、并发为 $B$，则解码 token 占比为</p>\n<div class=\"formula\">$$\\rho=\\frac{B\\cdot L_{\\text{out}}}{B\\cdot L_{\\text{out}}+B\\cdot L_{\\text{in}}}=\\frac{L_{\\text{out}}}{L_{\\text{out}}+L_{\\text{in}}}$$</div>\n<p>$\\rho$ 越接近 1，NVFP4 的带宽收益越能兑现。工程上把 $\\rho&gt;0.7$ 的负载称为“解码主导”，这是 NVFP4 专家权重的甜点区：长文生成、多轮对话的续写段、代码补全的流式输出都属于这一类。反过来，$\\rho&lt;0.3$ 的负载——长文档摘要、检索增强的整篇重写、批量分类——预填占了大头，权重带宽不是瓶颈，NVFP4 的收益被预填的算力需求稀释，而量化误差却要在整个前向里承担。</p>\n<p>代价是明确的：在解码主导负载下，专家权重从 FP16 压到 4 bit 使单卡驻留专家数提升，跨卡 All-to-All 的专家拉取次数下降，TPOT 的尾部被削平；但在预填主导负载下，同样的量化只降低了权重显存占用，对首 token 延迟（TTFT）几乎没有帮助，反而因为激活侧要额外做动态量化与缩放因子附加，引入可测量的固定开销。一个具体例子：同样是 8K 上下文的请求，若输出只有 200 token，$\\rho\\approx0.024$，NVFP4 的收益基本不可见；若输出 6K token，$\\rho\\approx0.43$，收益开始显现但仍被预填摊薄；只有当输出远超输入、且并发稳定时，$\\rho$ 才进入甜点区。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-21\">二十一 · 长度分布：尾部长度决定批大小上限，而非均值</h3>\n<p>长度分布对 NVFP4 负载配方的影响，集中在批大小的可行域上。连续批处理下，一个 batch 的显存占用由三部分构成：激活工作集、KV cache、以及当前 batch 触及的专家权重驻留量。前两项随 batch 内 token 总数线性增长，第三项则取决于 batch 内 token 路由到的专家集合的并集大小。NVFP4 把单个专家的权重体积压到 FP16 的 1/4，使“并集大小 × 单专家体积”这一项大幅缩小，于是批大小的约束从专家权重驻留转向 KV cache 与激活。</p>\n<p>但长度分布的尾部会破坏这个结论。设 batch 内请求长度服从重尾分布，最长请求长度为 $L_{\\max}$，则解码步的显存峰值近似为</p>\n<div class=\"formula\">$$M_{\\text{peak}}\\approx B\\cdot L_{\\max}\\cdot c_{\\text{kv}}+W_{\\text{exp}}\\cdot|E_{\\text{batch}}|+M_{\\text{act}}$$</div>\n<p>其中 $c_{\\text{kv}}$ 是每 token 每层的 KV 字节数，$W_{\\text{exp}}$ 是单专家 NVFP4 权重体积，$|E_{\\text{batch}}|$ 是 batch 触及的专家并集大小。重尾分布下 $L_{\\max}$ 远大于均值，KV 项按最长请求计费，批大小被尾部长度而非平均长度卡住。这意味着：在长度方差大的负载上，NVFP4 省下的专家权重显存并没有转化为更大的批，而是被 KV cache 吃掉——批大小不变，吞吐不变，只有单次解码的权重带宽下降带来 TPOT 改善。</p>\n<p>具体例子：一个混合负载，90% 请求输出 500 token，10% 请求输出 8K token。若按均值 1.25K 规划批大小，实际解码步的 KV 峰值由 8K 那条请求决定，批大小被迫压到远低于均值规划的值。此时 NVFP4 的正确用法不是去追求更大批，而是承认批被 KV 卡住，把收益定位在 TPOT 与单卡专家容量上；若要真正放大批，需要配合分页 KV 的回收策略，而这属于另一条路径，不在本配方内。</p>\n<p>工程判断：负载配方应把长度分布的第 95 百分位而非均值作为批大小规划的输入，并据此判断 NVFP4 的收益落在 TPOT 还是吞吐上。长度分布集中（方差小）时，NVFP4 的显存节省能直接换成批大小；长度分布重尾时，收益退化为纯带宽节省。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-22\">二十二 · 并发与批大小：专家并集大小是隐藏的批约束</h3>\n<p>并发数上升时，batch 内 token 路由到的专家并集 $|E_{\\text{batch}}|$ 随之增长，但增长是次线性的：router 的分布集中，热门专家被反复命中，并集很快饱和。NVFP4 让每个专家的权重体积缩小到 1/4，于是同样的显存预算能容纳更大的并集，或者说同样的并集占用更少显存。这是并发扩展的直接杠杆。</p>\n<p>代价出现在并集饱和之后。当 $|E_{\\text{batch}}|$ 接近单卡可驻留专家总数时，继续加并发不再增加并集，而是增加每个专家的 token 数，此时分组 GEMM 的每专家 M 维变大，算术强度上升，FP4 MMA 的算力密度开始发挥作用，瓶颈从带宽转向算力。这是一个拐点：拐点之前，NVFP4 的收益是带宽；拐点之后，收益是 tcgen05 原生 FP4 MMA 的吞吐。负载配方要识别当前并发处在拐点的哪一侧。</p>\n<p>伪代码思路：在批调度器里维护一个滑动窗口，估计最近若干解码步的专家并集大小与每专家平均 token 数，据此决定是否继续放大批。</p>\n<ul>\n<li>若 $|E_{\\text{batch}}|$ 仍在增长且每专家 token 数低于 MMA 的有效 M 下界，说明还在带宽区，放大批有收益；</li>\n<li>若 $|E_{\\text{batch}}|$ 饱和而每专家 token 数上升，说明进入算力区，此时应优先保证分组 GEMM 的块对齐，而不是继续加并发；</li>\n<li>若 $|E_{\\text{batch}}|$ 触及单卡驻留上限，说明专家权重驻留成为硬约束，需要缩小专家并行域或回退部分专家到 FP8 以腾出空间。</li>\n</ul>\n<p>具体代价：并发从带宽区跨到算力区时，TPOT 的下降曲线会变平，因为带宽不再是限制；此时若继续按“加并发降 TPOT”的直觉扩容，会看到 TPOT 不再改善而显存压力上升。这是负载配方里最常见的误判——把带宽区的线性收益外推到算力区。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-23\">二十三 · 负载不对时的三种失效形态</h3>\n<p>负载与配方不匹配时，失效不是渐进的，而是有明确形态的。第一种是预填主导负载上的“收益蒸发”：$\\rho$ 低，NVFP4 的权重带宽节省在总时延里占比很小，而激活侧动态量化与缩放因子附加的固定开销照常付出，净效果是 TTFT 略升、TPOT 略降，整体吞吐持平甚至微降。这种负载下不应启用 NVFP4 激活量化，权重可以保留 4-bit 以省显存，但激活回退 FP8 以减少每层的量化开销。</p>\n<p>第二种是长尾专家上的误差累积。router 分布重尾时，尾部专家样本稀少，4-bit 量化在这些专家上的误差缺乏校准，路由到它们的 token 输出偏移明显。负载配方要监控尾部专家的命中率：若尾部专家承载的 token 比例不可忽略，就必须对这些专家回退 FP8。误差上界由前文的 $\\epsilon\\le s/2$ 给出，但多层叠加后误差会放大，敏感层未回退时生成质量被破坏——这是定性表述，材料未给出具体精度下降数字。</p>\n<p>第三种是缩放因子元数据反噬。NVFP4 每 16 或 32 个元素共享一个 E8M0 缩放因子，block 越小，元数据越多。设 block 大小为 $b$、权重元素数为 $N$，元数据开销比例为</p>\n<div class=\"formula\">$$\\eta=\\frac{N/b\\cdot 1\\ \\text{byte}}{N/2\\ \\text{byte}}=\\frac{2}{b}$$</div>\n<p>$b=16$ 时元数据占权重体积的 12.5%，$b=32$ 时降到 6.25%。在带宽受限的解码阶段，元数据读取与权重读取走同一条 HBM 通路，$\\eta$ 直接吃掉 4-bit 带来的带宽节省。负载配方要在精度与带宽之间选 block 大小：长尾专家多、精度敏感的负载选 $b=16$ 保局部动态范围；专家分布集中、带宽压力大的负载选 $b=32$ 压元数据。这是一个显式的取舍，不是默认值。</p>\n<p>具体例子：一个并发稳定、长度集中的解码负载，专家并集饱和、每专家 token 数高，此时瓶颈在带宽，$b=32$ 的元数据节省直接转化为 TPOT 下降；同一个模型换到长尾专家命中率高的负载，$b=32$ 的量化误差在尾部累积，输出偏移可见，必须回退到 $b=16$ 并对敏感层用 FP8。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-24\">二十四 · 配方判据：把负载特征映射到量化档位</h3>\n<p>把上面的判据收拢成一张可执行的映射表。负载配方不是一套固定参数，而是按负载特征在权重精度、激活精度、block 大小、专家驻留策略四个维度上选档。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>负载特征</th><th>权重</th><th>激活</th><th>block</th><th>预期收益落点</th></tr>\n</thead>\n<tbody>\n<tr><td>解码主导、长度集中、并发高</td><td>NVFP4</td><td>NVFP4</td><td>32</td><td>TPOT 与吞吐双降</td></tr>\n<tr><td>解码主导、长尾专家命中高</td><td>NVFP4 + 敏感层 FP8</td><td>FP8</td><td>16</td><td>TPOT，吞吐持平</td></tr>\n<tr><td>预填主导、输出短</td><td>FP8 或 NVFP4 仅省显存</td><td>FP8</td><td>—</td><td>显存容量，时延无收益</td></tr>\n<tr><td>长度重尾、批被 KV 卡住</td><td>NVFP4</td><td>FP8</td><td>32</td><td>单卡专家容量与 TPOT</td></tr>\n<tr><td>并发跨越带宽区到算力区</td><td>NVFP4</td><td>NVFP4</td><td>32</td><td>FP4 MMA 算力密度</td></tr>\n</tbody>\n</table>\n<p>这张表的用法是：先用 $\\rho$ 判断是否进入解码主导区，再用长度分布的第 95 百分位判断批是否被 KV 卡住，再用尾部专家命中率判断是否需要 FP8 回退，最后用并发所处的区间判断收益落点是带宽还是算力。四个判据的顺序不能颠倒，因为前一个判据会否决后一个判据的收益前提。</p>\n<p>代价维度上，这张表对应四种资源：显存（专家驻留量）、带宽（解码权重读取）、算力（FP4 MMA 密度）、时延（TPOT/TTFT）。每一档的选择都是在四个维度上做显式取舍，没有一档同时在四个维度上最优。工程判断是：先锁定 SLO 的约束维度（TPOT 还是并发数），再在表里选档，而不是反过来先选量化格式再找负载。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-25\">二十五 · 容量规划中的负载配方接口</h3>\n<p>负载配方最终要落到容量规划上：给定 SLO 的 TPOT 目标与并发目标，反推需要多少张卡、每张卡驻留多少专家、专家并行域多大。NVFP4 在这里的作用是把“单卡专家驻留量”这个约束放松，从而缩小专家并行域，减少跨卡 All-to-All。设模型总专家数为 $E$、单卡可驻留专家数为 $E_{\\text{card}}$，则最小专家并行度为</p>\n<div class=\"formula\">$$P_{\\text{ep}}\\ge\\left\\lceil\\frac{E}{E_{\\text{card}}}\\right\\rceil$$</div>\n<p>$E_{\\text{card}}$ 与单专家权重体积成反比，NVFP4 把体积压到 1/4，$E_{\\text{card}}$ 相应放大，$P_{\\text{ep}}$ 下降。这是容量规划里最直接的杠杆：专家并行域缩小意味着 All-to-All 的跳数减少、通信开销下降，解码步的尾部延迟被削平。但这条杠杆有边界——$P_{\\text{ep}}$ 不能小于 1，且当 $E_{\\text{card}}$ 已经覆盖全部专家时，继续压精度不再带来并行度收益，只剩带宽收益。</p>\n<p>容量规划还要把负载配方的失效形态计入余量。长尾专家回退 FP8 会局部抬高显存占用，block 选 16 会抬高元数据开销，激活选 NVFP4 会抬高每层量化开销——这些都要在规划时留出余量，否则按纯 NVFP4 的理想体积算出的卡数在实际负载下不够。具体做法是把回退比例与元数据开销作为两个乘性因子计入单卡有效专家容量，再反推 $P_{\\text{ep}}$。</p>\n<p>最后的工程判断落在一个具体机制上：负载配方的正确性不取决于量化格式本身，而取决于批调度器是否把专家并集大小、每专家 token 数、尾部专家命中率这三个量作为运行时观测量反馈给量化档位选择。没有这个反馈回路，NVFP4 的收益就是静态的、按最坏情况打折的；有了它，才能在带宽区与算力区之间切换档位，把 4-bit 的显存与带宽收益真正兑现到 TPOT 与并发上。</p>\n<h3 id=\"alg-nvfp4-moe-weights-sec-26\">二十六 · 硬件档位与算力前提</h3>\n<p>NVFP4 部署的第一道门槛不是软件栈，而是芯片档位。只有具备 tcgen05 原生 FP4 MMA 的 Blackwell 部件（SM100/SM103 家族的 B200/B300、GB200/GB300 NVL72）才能让 4-bit 权重真正转化为吞吐；在缺少 FP4 MMA 通路的部件上，NVFP4 权重必须先反量化成 FP8 或 BF16 再进 MMA，此时省下的是 HBM 容量与读取带宽，付出的却是每层一次反量化开销和更高的寄存器压力，收益结构完全不同。因此配置思路的第一步是判定目标机器属于哪一档：原生 FP4 档、仅容量收益档、以及不支持微缩放格式的档位。三档对应三套不同的量化方案与并行拓扑，不能混用同一份配置模板。</p>\n<p>原生 FP4 档的算力密度相对 FP8 翻倍，这是 tcgen05 的指令级事实，但它只对满足形状约束的分组 GEMM 生效。MoE 解码中每个专家处理的 token 数随 router 分布剧烈波动，若单专家 token 数低于 MMA 的最小有效 tile，FP4 的高算力密度会被形状开销吃掉。工程判断是：把 FP4 MMA 的收益绑定在“专家批大小达到 tile 下限”的条件上，而不是无条件假定翻倍。代价侧要盯住一个量：解码阶段每 token 每层需要读取的专家权重字节数。权重从 FP16 压到 NVFP4 后该字节数降到四分之一，HBM 带宽瓶颈随之缓解，这正是本方案在显存与带宽受限场景下的核心卖点。</p>\n<p>具体例子：一台 8 卡 NVL72 节点承载专家总参数量远超单卡容量的 MoE 模型。若权重保持 FP8，专家并行域必须跨全部 8 卡切分，每层解码触发一轮 All-to-All；改用 NVFP4 后单卡可驻留的专家数上升，专家并行域可收缩到 4 卡甚至 2 卡，All-to-All 的参与方与消息量同步下降。这个例子说明硬件档位、量化位宽与并行拓扑三者是耦合的，配置时必须联合求解。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-27\">二十七 · 并行拓扑：以驻留量反推专家并行域</h3>\n<p>并行拓扑的设计变量不是“卡越多越好”，而是“单卡能驻留多少专家”。设单卡可用显存为 $M$，非专家部分（注意力权重、KV cache、激活缓冲、通信缓冲）占用 $M_{\\text{other}}$，单专家 NVFP4 权重加缩放因子元数据占用 $m_e$，则单卡可驻留专家数上界为</p>\n<div class=\"formula\">$$E_{\\text{local}}=\\left\\lfloor \\frac{M-M_{\\text{other}}}{m_e}\\right\\rfloor,\\quad m_e = \\frac{P_e}{2}+m_{\\text{scale}}$$</div>\n<p>其中 $P_e$ 为单专家参数量（字节计），除以 2 即 4-bit 权重体积，$m_{\\text{scale}}$ 是每 16 或 32 元素一个 E8M0 因子的元数据开销。专家并行域大小 $N_{\\text{ep}}$ 必须满足 $E_{\\text{total}}/N_{\\text{ep}} \\le E_{\\text{local}}$，否则就要引入专家换入换出或跨节点分发，解码延迟立刻劣化。这条不等式是拓扑设计的硬约束，也是 NVFP4 最直接的杠杆：$m_e$ 缩小四倍，$E_{\\text{local}}$ 近似放大四倍，$N_{\\text{ep}}$ 的下界随之下降。</p>\n<p>拓扑收缩带来两级收益。第一级是通信：All-to-All 的延迟与参与卡数、消息分片数正相关，$N_{\\text{ep}}$ 减半意味着每层解码的集合通信轮次与数据量同步下降。第二级是调度：更小的专家并行域让连续批处理的调度器可以把更多请求压在同一组卡上，提升专家权重的复用率。代价是单卡显存被专家权重挤占后，留给 KV cache 的空间变小，长上下文请求的并发数受限。因此拓扑决策必须与 KV 策略联动，不能单独拍板。</p>\n<p>具体例子：同一模型在 FP8 下需要 $N_{\\text{ep}}=8$，NVFP4 下若 $E_{\\text{local}}$ 放大到足以覆盖 $E_{\\text{total}}/4$，则可取 $N_{\\text{ep}}=4$，剩余 4 卡转为数据并行或专用于预填。此时需要重新核算每卡的 KV 预算，否则并发数目标会被显存挤爆。工程上建议把“专家驻留量—KV 预算—并发数”做成一张联动表，按档位逐行填数，而不是先定拓扑再补参数。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-28\">二十八 · 量化方案：权重 NVFP4、激活 FP8 与回退清单</h3>\n<p>量化方案的主干是权重 NVFP4、激活 FP8 或 NVFP4、累加器 FP32。权重侧离线按 block 量化，$w_q=\\text{round}(w/s)$，$s=\\max|w_{\\text{block}}|/\\text{FP4\\_MAX}$，每元素误差上界为 $s/2$；缩放因子以 E8M0 形式存储，反量化时 $\\hat{w}=s\\cdot q$ 参与 MMA。激活侧按 token 动态量化并附带缩放，累加器保持 FP32 以避免分组 GEMM 中的累加溢出。这套组合的关键取舍在激活精度：激活用 FP8 时数值更稳、回退路径更短；激活用 NVFP4 时算力密度更高，但多层叠加后误差放大风险上升，尤其在敏感层。</p>\n<p>回退清单是配置文件中必须显式列出的一项，而不是运行期临时判断。判定依据有两条：一是层的量化敏感度，注意力输出投影、路由 logits 前的线性层、以及长尾专家集中的层应回退 FP8；二是专家样本量，router 统计中触发次数低于阈值的专家，其 4-bit 量化误差缺乏足够 token 平均，输出偏移风险高，应将该专家的权重保留为 FP8 或对其输出做精度补偿。回退不是全有全无，而是按层、按专家粒度打标，配置中以掩码形式下发。</p>\n<p>代价侧要算清元数据账。缩放因子随 block 变小而增多：block 为 32 时每 32 元素一个因子，block 为 16 时翻倍。额外元数据读取会占用本已紧张的 HBM 带宽，当 block 小到元数据字节数与权重字节数可比时，4-bit 带来的带宽节省被抵消。工程判断是：优先选 32 元素 block，仅在局部动态范围确实跨数量级的层降到 16，并对这些层单独核算带宽预算。具体例子：某层权重动态范围在一个 block 内跨越两个数量级，用 32 元素共享因子会把小值全部压成零，此时降到 16 元素 block 并接受元数据开销，比整层回退 FP8 更划算。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-29\">二十九 · KV 策略：与专家权重争夺同一块显存</h3>\n<p>NVFP4 省下的显存不会自动变成并发能力，它首先被专家驻留量吃掉。KV 策略的设计必须建立在“扣除专家权重后的剩余显存”之上。设每卡 KV 预算为 $M_{\\text{kv}}=M-M_{\\text{other}}-E_{\\text{local}}\\cdot m_e$，单请求每 token 的 KV 占用为 $k$ 字节（随层数、头数、头维度、KV 位宽变化），则并发上限近似为</p>\n<div class=\"formula\">$$C_{\\max}\\approx \\frac{M_{\\text{kv}}}{k\\cdot L_{\\text{ctx}}}$$</div>\n<p>其中 $L_{\\text{ctx}}$ 为平均上下文长度。分页 KV 的块管理细节属于另一条目的主题，此处只强调与本方案的耦合点：KV 位宽的选择应与专家权重的位宽决策一起做。若专家权重已压到 NVFP4 而 KV 仍用 FP16，KV 往往成为显存主占用项，此时把 KV 压到 FP8 能在不触碰专家精度的前提下放大 $C_{\\max}$；反之若 KV 已压缩而专家权重仍是 FP8，则应优先把专家权重降到 NVFP4。两者谁先压，取决于实测的显存占用排序，而不是固定顺序。</p>\n<p>代价是 KV 压缩引入的精度损失与专家量化误差会叠加。长上下文请求中 KV 误差随位置累积，若同时命中长尾专家，两条误差路径合流，输出偏移更难控制。工程判断是：对长上下文流量单独设一条精度策略，KV 保持较高位宽或对敏感头不做压缩，把压缩预算留给专家权重。具体例子：面向 TPOT 与并发数为目标的解码服务，若并发目标要求 $C_{\\max}$ 翻倍而专家权重已无可压缩空间，则选择 KV FP8 加敏感头豁免，而不是继续压低专家位宽——后者会直接破坏长尾专家的输出质量。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-30\">三十 · 调度参数：批大小、容量因子与 piggyback 的边界</h3>\n<p>调度参数的第一项是批大小上限，它受专家权重驻留量约束而非算力约束。解码时每增加一个请求，就可能触发新的专家激活，若激活的专家不在本卡驻留集合内，就要走跨卡分发。因此批大小应设为“使激活专家集合尽量落在 $E_{\\text{local}}$ 内”的值，而不是简单取显存能容纳的最大 batch。容量因子路由与令牌丢弃的机制属于另一条目，此处只取它的输出作为调度输入：容量因子决定每专家处理的 token 上限，进而决定单批内专家激活的分布宽度。</p>\n<p>第二项是预填与解码的 piggyback 边界。分块预填与解码 piggyback 的具体做法在别处展开，本方案关心的是它与 FP4 权重的交互：预填阶段是算力密集、解码阶段是带宽密集，两者共享同一份 NVFP4 权重时，预填的大 token 数会让 FP4 MMA 的形状开销摊薄，收益最明显；解码的小 batch 则更依赖权重读取带宽的节省。调度上应把预填块大小设为能让 FP4 MMA 达到有效 tile 的下限，而不是沿用 FP8 时代的块大小，否则预填阶段的算力密度优势无法兑现。</p>\n<p>第三项是超时与降级参数。当长尾专家被高频命中导致跨卡分发增多时，TPOT 会抖动，调度器需要一条降级路径：临时把该专家复制到更多卡、或将其权重回退 FP8 以换取更短的加载路径。这条路径的触发阈值应基于实测的 TPOT 分位数，而不是固定计数。具体例子：某服务在流量高峰时 router 分布偏移，少数专家承接了大量 token，跨卡 All-to-All 成为 TPOT 主因；调度器按 TPOT 的 P99 触发专家复制，把热点专家在本卡多驻留一份，代价是 $E_{\\text{local}}$ 下降、并发上限略降，但尾延迟收敛。这是用显存换稳定性的典型调度动作。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-31\">三十一 · 可复现的配置求解顺序</h3>\n<p>把上述变量串成一条可复现的求解链，顺序不能颠倒。第一步定硬件档位，确认是否具备原生 FP4 MMA；第二步按 $E_{\\text{local}}$ 不等式反推 $N_{\\text{ep}}$ 的下界，并检查收缩后的拓扑是否仍满足通信预算；第三步在剩余显存上分配 KV 预算，按 $C_{\\max}$ 公式核对并发目标，必要时调整 KV 位宽；第四步生成量化回退掩码，按层敏感度与专家样本量打标；第五步设定批大小上限与预填块大小，使 FP4 MMA 形状开销摊薄；第六步配置降级阈值与热点专家复制策略。每一步的输出是下一步的输入，任一步不满足就回退上一步调整，而不是在最后打补丁。</p>\n<p>这条链的验证方式是分层压测而非单点跑分：先固定并发、扫上下文长度看 TPOT 曲线拐点，再固定上下文、扫并发看显存余量与专家分发比例，最后注入长尾专家偏置流量看尾延迟与输出偏移。三个维度的交点就是该档位的稳定工作点。工程判断上，NVFP4 配置的成败不在峰值吞吐，而在“专家驻留量、KV 预算、并发数”三者能否在 SLO 内同时成立；任何一项被挤爆，4-bit 的带宽收益都会被调度抖动抵消。配置文件的最终形态应是一张按档位分行的参数表，每行包含 $N_{\\text{ep}}$、KV 位宽、回退掩码、批大小上限与降级阈值，随硬件档位切换整行替换，而不是逐项手调。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-32\">三十二 · 配方落地时的边界：元数据带宽、回退粒度与专家并行域收缩</h3>\n<p>这套配方的收益并非无条件成立，最容易被忽视的失效点是缩放因子的元数据开销。NVFP4 每 16 或 32 个元素共享一个 E8M0 缩放因子，block 取 16 时每个权重元素平均附带 0.5 bit 元数据，block 取 32 时降到 0.25 bit；但元数据是独立寻址的，解码时按 router 选中的专家加载权重块，必须同时读取权重块与对应的缩放因子数组，两次访存意味着有效带宽需求为 <span class=\"formula\">$$B_{\\text{eff}}=B_w\\left(1+\\frac{8}{b\\cdot 4}\\right)$$</span>（$b$ 为 block 元素数，$B_w$ 为纯 4-bit 权重字节数）。当 $b=16$ 时元数据占权重字节的 12.5%，若 L2 命中率不足、缩放因子数组无法与权重块合并成一次事务，4-bit 相对 FP8 的带宽节省会被部分吃掉。工程判断是：优先选 32 元素的 block，并让缩放因子与权重块在显存中交错布局，使一次 128B 事务同时覆盖两者。</p>\n<p>回退粒度决定稳定性技巧的系统代价。把敏感层整体回退到 FP8 会让这些层的权重显存翻倍，若回退层恰好是专家权重占比高的层，单卡可驻留的专家数下降，专家并行域被迫扩大，跨卡 All-to-All 流量回升——这正是 NVFP4 想削减的那部分代价。更细的做法是按专家而非按层回退：长尾专家样本少、4-bit 误差在其上累积，可只把这些专家的权重保留为 FP8，其余专家走 NVFP4，混合精度分组 GEMM 由 tcgen05 按块调度。代价是 kernel 需要维护两套 MMA 路径与两套缩放语义，编译期分支增多，单次解码的指令开销上升，TPOT 的尾部抖动变大。</p>\n<p>调度参数必须与专家驻留量绑定。batch 大小不能按激活显存或 KV cache 单独定，而应满足 <span class=\"formula\">$$\\text{batch}\\le\\frac{M_{\\text{HBM}}-M_{\\text{KV}}-M_{\\text{act}}}{W_{\\text{exp}}\\cdot N_{\\text{local}}}$$</span>，其中 $W_{\\text{exp}}$ 为单专家 4-bit 权重字节数，$N_{\\text{local}}$ 为单卡驻留专家数。把专家权重压到 FP16 的 1/4 后 $N_{\\text{local}}$ 上升，专家并行域收缩，All-to-All 的跳数与消息量下降，这是吞吐收益的主要来源；但 batch 一旦超过该上限，专家权重被换出，解码从带宽受限滑向容量受限，TPOT 出现阶跃式恶化。可复现的配置思路是：先按目标并发与 TPOT SLO 反推所需 $N_{\\text{local}}$，再据此确定并行拓扑与回退专家集合，最后用实测的元数据读取占比校准 block 大小。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>block 过小，缩放因子无法合并访存</td><td>有效带宽收益被抵消，解码延迟不降</td><td>block 取 32，元数据与权重交错布局</td></tr><tr><td>按层整体回退 FP8</td><td>专家驻留量下降，All-to-All 回升</td><td>按专家回退，混合精度分组 GEMM</td></tr><tr><td>batch 超过专家驻留上限</td><td>专家换出，TPOT 阶跃恶化</td><td>以 $N_{\\text{local}}$ 反推 batch 上限</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-moe-weights-sec-33\">三十三 · 显存账：4 bit 省下来的是驻留量，不是峰值</h3>\n<p>NVFP4 把专家权重压到 FP16 的 1/4，直接改变的是“单卡能驻留多少专家”这个约束。设专家并行度为 $E_p$、单专家参数量 $P_e$、每元素字节数 $b$，则单卡专家权重驻留量为</p>\n<div class=\"formula\">$$M_{\\text{exp}} = \\frac{E_{\\text{total}}}{E_p}\\cdot P_e\\cdot b + M_{\\text{scale}}$$</div>\n<p>其中 $M_{\\text{scale}}$ 是缩放因子元数据。NVFP4 每 16 个元素共享一个 E8M0 缩放因子，即每 16 个 4-bit 元素（8 字节）附带 1 字节，元数据开销约为权重的 12.5%；若 block 取 32，则降到约 6.25%。这一项不能忽略：它把“1/4”的实际收益压到约 1/4.5 至 1/4.1 之间。工程判断是 block 取 32 在多数解码负载下更划算，只有在权重分布极不均匀、长尾专家动态范围跨度大的层才回退到 16。</p>\n<p>更关键的是峰值显存与驻留显存不是一回事。解码阶段激活按 token 动态量化到 FP8/NVFP4，激活张量本身很小，但 tcgen05 FP4 MMA 的累加器必须保持 FP32，分组 GEMM 的中间结果与反量化写回缓冲会形成瞬时峰值。当 batch 拉大、单次路由命中的专家数上升时，峰值由“同时活跃的专家块数 × 每块反量化缓冲”决定，而不是由总驻留量决定。一个具体例子：某层路由命中 8 个专家、每个专家权重块 4 MB（NVFP4 后），若融合核一次性预取全部块并各自开 FP32 累加缓冲，峰值可达数十 MB 量级，足以把原本算好的驻留余量吃掉。因此容量规划要按“驻留 + 活跃块峰值”双账本算，而不是只按 1/4 折算。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-34\">三十四 · 带宽账：HBM 读取与缩放因子的拉锯</h3>\n<p>解码阶段每 token 只做一次极小的矩阵向量式乘加，算术强度极低，HBM 带宽是硬瓶颈。NVFP4 把每专家权重的读取字节数降到 1/4，理论上解码吞吐可近似按带宽反比提升：</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{mem}} \\approx \\frac{\\sum_{e\\in \\text{hit}} \\left(V_e\\cdot b + V_e/16\\right)}{B_{\\text{HBM}}\\cdot \\eta}$$</div>\n<p>其中 $V_e$ 是专家元素数，$\\eta$ 是有效带宽利用率。分母里 $V_e/16$ 就是缩放因子读取项——它和权重读取走同一条 HBM 路径，无法被缓存完全吸收，因为每次路由命中的专家组合都在变。block 越小，这一项越大；当 block 从 32 降到 16，元数据翻倍，若 $\\eta$ 本就不高（分组 GEMM 的 gather 模式访存不连续），额外读取开销会把 4-bit 权重的带宽节省抵消掉一部分。这正是失败模式里“block 太小时带宽收益被抵消”的定量来源。</p>\n<p>具体机制上，缓解手段是让缩放因子与权重块在物理布局上交错存放（interleaved），使一次 128 字节的 cache line 同时携带权重与对应缩放，避免两次独立访存。代价是离线量化时要做布局重排，且分组 GEMM 的索引计算变复杂，融合核的寄存器压力上升。工程上这笔交易通常值得：解码路径的瓶颈在 HBM 不在指令发射，多几条索引指令换一次访存合并是净赚。另一个代价是尾延迟——路由命中的专家若分散在多个不连续块，gather 的访存模式会退化，单 token 的 TPOT 抖动变大，而平均吞吐看起来仍然正常。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-35\">三十五 · 通信账：专家并行域缩小与 All-to-All 的二次效应</h3>\n<p>NVFP4 让单卡驻留更多专家，直接后果是专家并行域 $E_p$ 可以缩小。All-to-All 的通信量近似为</p>\n<div class=\"formula\">$$V_{\\text{A2A}} \\approx 2\\cdot T\\cdot d\\cdot b_{\\text{act}}\\cdot \\frac{E_p-1}{E_p}$$</div>\n<p>$T$ 为 token 数、$d$ 为隐藏维、$b_{\\text{act}}$ 为激活字节数。$E_p$ 缩小使每 token 需要跨卡发送的专家激活比例下降，但注意激活侧仍是 FP8 或 NVFP4，$b_{\\text{act}}$ 的缩减幅度小于权重侧——权重省了 4 倍，激活只省 2 倍（FP8 对 FP16）或 4 倍（NVFP4 对 FP16）。这意味着通信账的改善主要来自 $E_p$ 缩小而非激活位宽，二者不可混算。一个具体例子：原本 8 卡专家并行、每卡 16 个专家，压到 NVFP4 后每卡可驻留 64 个专家，$E_p$ 从 8 降到 2，All-to-All 的参与方从 8 降到 2，跨卡跳数与 NCCL 的 ring 步数同步下降，尾延迟的抖动源随之减少。</p>\n<p>但通信账有一个反向效应：$E_p$ 缩小后单卡要处理的专家数变多，分组 GEMM 的分组数上升，tcgen05 FP4 MMA 的 tile 调度更容易出现“小组碎片”，SM 利用率下降。这不是通信问题而是算力密度问题——算力密度翻倍的前提是分组足够大、能填满 MMA 的 tile。工程判断是：$E_p$ 缩小到 2 或 1 时，必须保证每卡命中的专家 token 数足以形成连续分组，否则省下的通信被算力碎片吃掉。NVLink 5 的高带宽降低了跨卡代价，反而让“多留几个卡做专家并行、换取更大分组”成为可选项，这是拓扑选择上容易被忽略的权衡。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-36\">三十六 · 功耗与热：算力密度翻倍后的新约束</h3>\n<p>tcgen05 原生 FP4 MMA 使算力密度翻倍，但解码负载的功耗结构并不随算力线性变化。解码时 HBM 读取占比高、MMA 占空比低，NVFP4 省下的是 HBM 访问次数，因此功耗下降主要来自显存子系统而非计算单元。真正让功耗上升的是反量化与缩放应用：每个权重块在进入 MMA 前要做 $\\hat{w}=s\\cdot q$ 的缩放，FP32 累加器与缩放乘法在融合核里持续运行，这部分是纯计算开销，在低 batch 解码时反而成为功耗的边际增量。</p>\n<p>规模上去以后，功耗约束先于带宽约束显现的场景是整机柜部署：GB200/GB300 NVL72 的功率预算固定，单卡功耗上升会压缩可同时满频运行的卡数，进而压缩有效并行度。一个具体机制是融合核的缩放应用可以部分下沉到 MMA 的输入侧——tcgen05 的 FP4 输入路径支持按 block 携带缩放，把缩放乘法从 CUDA 核搬到张量核内部，减少 SM 上的 FP32 运算量，代价是缩放因子的布局必须与 MMA 的 block 划分严格对齐，离线量化时就要固定 block 边界，不能按层自适应。这个约束会反过来限制“敏感层回退 FP8”的灵活性：同一层内混用 FP4 与 FP8 时，block 边界不一致会导致融合核走两条路径，功耗与延迟都变差。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-37\">三十七 · 尾延迟：长尾专家与量化误差的耦合</h3>\n<p>平均吞吐好看不等于 SLO 达标。NVFP4 的尾延迟有两个独立来源，且会耦合。第一个来源是路由：长尾专家样本少，命中频率低，其权重块在 HBM 中缺乏访问局部性，gather 时更容易触发不连续的访存，单 token 的 TPOT 出现尖峰。第二个来源是量化误差：4-bit 量化在长尾专家上误差累积，敏感层未回退 FP8 时，FP4 激活量化误差会在多层叠加后放大，破坏生成质量——这不是延迟问题，但会迫使系统提高 batch 或增加重试，间接拉高尾延迟。</p>\n<p>工程上的判断是把两者分开治理：长尾专家的访存尖峰用权重布局解决（把低频专家块集中放置、预取策略按命中频率分级），量化误差用敏感层回退解决。回退的代价是显存账本被打破——回退层按 FP8 存储，单卡驻留量下降，$E_p$ 可能被迫回升，通信量随之上升。因此回退比例必须纳入容量规划：设回退层占比 $\\rho$，则有效每元素字节数为</p>\n<div class=\"formula\">$$b_{\\text{eff}} = (1-\\rho)\\cdot 0.5 + \\rho\\cdot 1.0 + \\text{元数据}$$</div>\n<p>$\\rho$ 每上升 10 个百分点，驻留量收益就少一截。一个具体例子：若某 MoE 模型有若干层对激活量化极敏感，全部回退 FP8，则这些层的专家权重按 FP8 存储，单卡可驻留专家数下降，原本 $E_p=2$ 的拓扑可能要回到 $E_p=4$，All-to-All 通信量翻倍，尾延迟的抖动源重新出现。这就是“规模上去以后哪里先崩”的答案：不是 HBM 带宽先崩，而是回退比例上升导致驻留量下降、并行域回升、通信与尾延迟同时恶化，形成一个正反馈。</p>\n<p>抑制这个反馈的具体机制是分层量化策略与在线监控结合：离线量化时按层记录量化误差敏感度，部署时对回退层单独标记，容量规划按 $b_{\\text{eff}}$ 而非理论 1/4 计算驻留上限；同时在解码路径上监控长尾专家的 TPOT 分位数，一旦尖峰超过阈值就触发该专家的权重块重排或预取升级，而不是全局提高 batch。这套机制把尾延迟治理从“调 batch”变成“调布局”，代价是需要额外的元数据与运行时监控开销，但避免了回退比例上升引发的连锁反应。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-38\">三十八 · 四比特专家驻留之后：带宽账本、元数据税与长尾专家的尾延迟</h3>\n<p>把专家权重压到 NVFP4 之后，系统最先变化的不是算力，而是<strong>驻留容量与专家并行域的半径</strong>。权重显存降到 FP16 的 1/4，意味着同一张 B200 的 HBM 里能塞下四倍数量的专家，原本需要跨节点 All-to-All 才能凑齐的专家集合，现在可以在单个 NVLink 域内闭合。这一步的收益是双重的：既省了显存，也把解码阶段最贵的跨卡通信从关键路径上摘掉了一部分。但容量红利有明确的天花板——它只对“权重驻留”有效，对 KV cache 无效。当 batch 被推高、上下文被拉长，KV cache 会迅速吃掉量化省下来的那部分 HBM，此时系统的约束点从“专家放不下”切换为“KV 放不下”，NVFP4 的边际收益随之归零。容量规划时必须把这两本账分开算：专家权重按 4 bit 折算后的驻留量，与 KV cache 按每 token 每层字节数折算的增量，谁先触顶决定了该不该继续加 batch。</p>\n<p>带宽账本则更微妙。解码阶段每生成一个 token，都要把 router 选中的专家权重从 HBM 读进 SM，读的量是 $E_{\\text{active}}\\times d_{\\text{model}}\\times d_{\\text{ffn}}\\times b_w$，其中 $b_w$ 是每权重比特数。4 bit 相对 FP8 把这一项砍半，理论上解码带宽瓶颈显著缓解。但真实带宽消耗要加上缩放因子的元数据税：每 16 或 32 个元素共享一个 E8M0 因子，即每 16 个 4-bit 权重（8 字节）额外带 1 字节因子，元数据占比约 1/9；若 block 缩到 8 个元素，占比升到约 1/5，此时 4-bit 权重本身的带宽节省被元数据读取抵消掉相当一部分。用有效位宽表达更清楚：</p>\n<div class=\"formula\">$$b_{\\text{eff}}=b_w+\\frac{8}{B_{\\text{block}}}\\ \\text{bit/元素}$$</div>\n<p>取 $b_w=4$、$B_{\\text{block}}=16$ 得 4.5 bit，相对 FP8 的 8 bit 仍是近 1.8 倍的有效带宽压缩；取 $B_{\\text{block}}=8$ 则升到 5 bit，压缩比降到 1.6。这就是“block 太小时带宽收益被抵消”的定量形态——它不是一个模糊的警告，而是一条可以直接放进容量模型的加法项。工程判断因此很直接：在 tcgen05 FP4 MMA 的 fragment 布局允许的前提下，优先用 16 或 32 元素的 block，把元数据税压在 10% 量级，而不是为了局部动态范围去追更细的粒度。</p>\n<p>规模上去以后最先崩的通常不是吞吐，而是<strong>尾延迟</strong>，且崩点集中在长尾专家上。长尾专家样本少，4-bit 量化的舍入误差在其上累积得更充分，路由到这些专家的 token 输出会明显偏移；更麻烦的是这种偏移具有突发性——大部分 token 走热专家、精度正常，少数 token 命中冷专家时质量骤降，表现为生成结果的间歇性异常而非整体劣化，监控上极难用平均指标捕获。敏感层若不回退 FP8，FP4 激活量化误差还会在多层叠加后放大。稳定性技巧因此必须落到层粒度：对量化敏感层与长尾专家保留 FP8 路径，形成 NVFP4 与 FP8 混合的权重池。代价是显存收益不再整齐——回退层按 8 bit 驻留，混合池的实际压缩比介于 4 与 8 bit 之间，专家并行域的收缩幅度也要按最坏层的位宽重新估算。</p>\n<table class=\"mini\"><thead><tr><th>约束点</th><th>触发条件</th><th>系统代价</th></tr></thead><tbody><tr><td>KV cache 触顶</td><td>batch 与上下文推高，量化省下的 HBM 被 KV 吃掉</td><td>驻留专家数回退，跨卡 All-to-All 重新进入关键路径</td></tr><tr><td>元数据税</td><td>block 缩到 8 元素量级</td><td>有效位宽升至约 5 bit，带宽压缩比下降</td></tr><tr><td>长尾专家误差</td><td>冷专家未回退 FP8</td><td>尾延迟与输出偏移，TPOT 的 P99 恶化</td></tr><tr><td>功耗墙</td><td>FP4 MMA 算力密度翻倍后持续高利用率</td><td>机架功率预算约束并发上限，抵消吞吐收益</td></tr></tbody></table>\n<p>功耗这一项常被忽略：tcgen05 原生 FP4 MMA 让算力密度翻倍，单位时间完成的 MAC 数上升，若调度器把腾出来的算力直接换成更高并发，机架功率预算会先于显存触顶。GB200 NVL72 这类整柜形态里，功率是共享资源，单卡提频或提并发的收益会被邻卡的功耗预算挤压。因此 NVFP4 的正确用法不是“压完权重就无脑加 batch”，而是把省下的带宽与显存折算成更低的 TPOT 目标或更小的并行域，把算力密度红利换成 SLO 余量而非峰值吞吐。最终落在具体机制上：解码循环里按 router 输出加载 4-bit 专家块、附带 E8M0 因子、tcgen05 分组 GEMM 以 FP32 累加、反量化写回——这条链路的速度上限由最慢的那个长尾专家块决定，而不是由平均位宽决定。</p>\n<h3 id=\"alg-nvfp4-moe-weights-sec-39\">三十九 · 精度漂移的定位：从长尾专家到敏感层</h3>\n<p>NVFP4 的误差结构不是均匀的。微缩放格式把每 16 或 32 个元素绑到一个 E8M0 缩放因子上，单块内的量化误差上界是 <span class=\"formula\">$$\\epsilon\\le \\frac{s}{2}$$</span>，其中 <span class=\"formula\">$$s=\\frac{\\max|w_{\\text{block}}|}{\\text{FP4\\_MAX}}$$</span>。这意味着块内动态范围越大，绝对误差越大；而长尾专家恰恰是那种权重分布被少数离群通道撑开的专家——样本少、校准不充分、router 偶尔才把 token 送过来，离线量化时统计量本身就欠采样。诊断的第一原则是把“整体 PPL 掉了多少”拆成“哪些专家、哪些层、哪些 token 贡献了误差”。</p>\n<p>工程上可落地的做法是在离线量化阶段为每个专家块记录两个量：块内 <span class=\"formula\">$$\\max|w|$$</span> 与量化后重建误差 <span class=\"formula\">$$\\|w-\\hat w\\|_2/\\|w\\|_2$$</span>，按专家 ID 落成一张表。推理侧再用 router 的选专家直方图与该表做加权，得到“按实际路由频率加权的期望误差”。长尾专家若误差高但路由频率极低，对整体质量影响有限；反之，一个路由频率中等、误差偏高的专家才是真凶。敏感层判定则依赖逐层激活量化的溢出统计：FP4 激活的动态范围窄，某层若频繁触及 FP4_MAX 饱和，误差会在后续层叠加放大，这类层必须回退 FP8。代价上，逐层回退不是免费的——一层从 NVFP4 回到 FP8，该层专家权重显存翻倍，直接侵蚀“单卡容纳更多专家、缩小专家并行域”的收益，因此回退清单要按层粒度精确到个位数，而不是整块回退。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-40\">四十 · OOM 的三条来源与显存账本</h3>\n<p>NVFP4 部署里的 OOM 很少是“权重放不下”这么简单，它通常来自三处叠加。第一是缩放因子元数据：block 越小，每元素摊到的 E8M0 因子越多，4-bit 权重省下的带宽与显存被元数据部分抵消，block 尺寸的选择直接决定这笔账是否划算。第二是分页 KV 与专家权重的共存——KV cache 随并发线性增长，而专家权重是常驻的，两者抢同一块 HBM；当 batch 拉高时 KV 先吃满，随后触发专家权重的换入换出。第三是激活量化的临时缓冲与 FP32 累加器：tcgen05 FP4 MMA 的累加器保持 FP32，分组 GEMM 的中间结果按 token 数×隐藏维×FP32 计，长序列预填时这块临时显存不可忽略。</p>\n<p>诊断要建立显存账本而不是看一个总数。把 HBM 占用拆成常驻专家权重（含缩放因子）、KV 分页池、激活与累加器临时区、通信缓冲四栏，每栏设阈值告警。OOM 发生时先看是哪一栏越界：若是 KV 栏，说明并发上限估高了，应收紧 batch 或调低分页块预留；若是临时区，说明预填 chunk 太大，应减小分块预填的 chunk 尺寸；若是权重栏且伴随专家换入，说明专家并行域切得不够细或回退 FP8 的层太多。一个具体判断：当缩放因子元数据占比超过权重本身的某个可观比例时，说明 block 选得过小，应放大 block 换取带宽与显存，而不是继续压 bit 数。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-41\">四十一 · 批抖动与路由不均的耦合诊断</h3>\n<p>批抖动在 MoE 解码里几乎总是路由不均的下游症状。router 对每个 token 选 top-k 专家，各专家的被选次数在 batch 内服从重尾分布；容量因子路由会丢弃超出容量的 token，而丢弃率随 batch 组成波动——同一 batch 里若长尾专家突然被集中选中，容量被打满，token 被丢弃，输出分布偏移，表现为 TPOT 正常但质量抖动。反过来，若容量因子设得宽松，专家计算量不均导致分组 GEMM 的尾块拖长，表现为 TPOT 尖刺。诊断要把“每专家实际 token 数 / 容量”这个比值按 step 采样，画出随时间的热图：持续贴顶的专家是容量瓶颈，长期空转的专家是并行域划分过宽。</p>\n<p>系统代价上，路由不均直接转化为分组 GEMM 的负载不均：tcgen05 FP4 MMA 的分组 GEMM 按专家分段执行，最慢的那一段决定该 step 的完成时间，因此 TPOT 的 P99 由最大专家负载而非平均负载决定。缓解手段不是简单调大容量因子（那会推高显存与算力浪费），而是把专家按历史路由频率做重排布，让高频专家落在同一张卡上以减少跨卡 All-to-All，同时把容量因子按专家粒度而非全局粒度设置。监控指标建议同时盯三个：全局丢弃率、单专家容量贴顶率、分组 GEMM 各段耗时的极差。三者同时抬升，基本可判定为路由不均而非硬件抖动。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-42\">四十二 · 尾延迟尖刺的归因路径</h3>\n<p>尾延迟尖刺要区分“计算尖刺”与“数据尖刺”。计算侧尖刺来自专家负载极差与预填/解码 piggyback 的相互干扰：一个长预填 chunk 插进解码流，会占满 SM 与 HBM 带宽，让同期解码 step 的 TPOT 抬高。数据侧尖刺来自专家权重的换入与缩放因子元数据的额外读取——当 router 选中一个当前不在本卡的专家，需要跨卡取 4-bit 权重块及其缩放因子，这笔传输的延迟远高于本地读取，且随专家并行域扩大而增加。归因方法是给每个 step 打两个时间戳：MMA 开始到结束的纯计算时间，以及权重就绪前的等待时间。若等待时间占比突增，是数据侧；若纯计算时间突增且伴随某专家段特别长，是计算侧。</p>\n<p>可操作的抑制手段：对数据侧，把高频专家做副本驻留或按路由频率做亲和调度，减少跨卡取权重；对计算侧，限制单次预填 chunk 的 token 上限，让预填与解码的时间片交错而非互相抢占。注意这里有个反直觉的取舍：把专家权重压到 4 bit 本是为了缓解 HBM 带宽瓶颈，但如果 block 太小导致缩放因子读取开销抵消了带宽节省，尾延迟反而变差——这正是“量化更狠不等于更快”的典型失败模式，诊断时必须把元数据读取计入有效带宽，而不是只看权重位宽。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-43\">四十三 · 监控面与回滚闸门</h3>\n<p>监控要分三层布点。第一层是数值层：逐层激活饱和率、逐专家重建误差、输出 logits 的分布偏移（与 FP8 基线比对），这层采样频率可以低但必须覆盖全部专家。第二层是资源层：显存四栏账本、有效带宽（含元数据）、分组 GEMM 分段耗时。第三层是服务层：TPOT 的 P50/P99、丢弃率、路由直方图的 KL 散度随时间的变化。三层联动才能把“质量掉了”快速定位到“某个长尾专家在某个 step 被集中路由且该专家未回退 FP8”。</p>\n<p>回滚闸门要预先定义而非事后拍脑袋。建议三道：其一，逐层激活饱和率或输出分布偏移超过预设阈值，自动把该层从 NVFP4 切回 FP8（层粒度回滚，保留其余层的显存收益）；其二，单专家容量贴顶率与丢弃率同时越线，回滚容量因子配置或触发专家重排布；其三，尾延迟 P99 连续多个窗口越线且归因为数据侧，回滚专家并行域划分或提高高频专家副本数。回滚本身有代价：切回 FP8 使该层权重显存翻倍，可能触发第二节的权重栏 OOM，因此回滚动作要与显存账本联动，先确认回滚后有足够余量再执行。工程判断上，回滚清单应当版本化并随量化配方一起发布——把“哪些层不许压到 FP4”写进部署配置，比在故障时现场判断可靠得多。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-44\">四十四 · 边界条件、失效链与可回滚的监控面</h3>\n<p>NVFP4 专家权重的收益不是无条件成立的，它把风险从“放不下”转移到了“算得偏”。量化误差的上界由缩放因子决定：<div class=\"formula\">$$\\hat{w}=s\\cdot q,\\quad s=2^{e-127},\\quad |w-\\hat{w}|\\le \\frac{s}{2}$$</div>每 16 或 32 个元素共享一个 E8M0 缩放因子，意味着 block 内动态范围被压缩成单一指数；一旦 block 内出现远大于其余元素的离群值，$s$ 被抬高，同 block 的小幅值元素相对误差随之放大。长尾专家恰恰是这种结构的温床——样本少、权重分布未被充分约束，4-bit 量化误差在其上累积，路由到这些专家的 token 输出出现可观测偏移。诊断上不能只看全局 loss，要在 router 侧按专家维度打点：记录每个专家的被选中频次、该专家输出与 FP8 回退路径输出的余弦偏差、以及 top-k 概率分布的熵变。当某专家的偏差统计量持续越过阈值，就把它单独钉在 FP8，而不是整层回退。</p>\n<p>第二类失效来自元数据。缩放因子随 block 变小而线性增多，解码时按 router 选中的专家加载 4-bit 权重块，同时要读这批 E8M0 因子；block 太小时，额外读取开销抵消掉 4-bit 权重带来的带宽节省。工程判断是算有效字节率而非名义位宽：设 block 大小为 $B$、每元素 4 bit、每 block 一个 1 字节因子，则每元素有效位宽为 $4+8/B$，$B=16$ 时是 4.5 bit，$B=8$ 时升到 5 bit，再叠加对齐与描述符开销，收益迅速衰减。监控面应把“专家权重读取字节/ token”与“因子读取字节/ token”分开计量，一旦因子占比超过设定比例，说明 block 配置已越过拐点，应回退到更大 block 或改回 FP8。</p>\n<p>第三类是系统级抖动，与数值无关但与量化强耦合。专家权重压到 4 bit 后单卡可容纳更多专家，专家并行域缩小，All-to-All 流量下降，但单卡驻留的专家集合变大，router 分布的任何偏斜都会直接转化为卡内 HBM 带宽争用与 SM 占用不均：热点专家所在卡 TPOT 抬升，冷门卡空转，形成批抖动与尾延迟尖刺。表现为同一 batch 内 token 完成时间方差变大、连续批处理的有效 batch 缩水。诊断要把每卡的专家命中直方图、FP4 MMA 利用率、HBM 读带宽三者对齐到同一时间窗；若某卡命中率显著高于均值而 MMA 利用率并不高，瓶颈在权重读取而非算力，此时缩小 block 无益，应做专家复制或路由均衡。OOM 则多见于激活侧：NVFP4 激活按 token 动态量化并附带缩放，临时缓冲与 FP32 累加器随并发上升，容量规划要按“权重驻留 + 峰值激活 + 因子元数据”三段分别留量，而不是只按权重估算。</p>\n<p>回滚必须是分级的、可在线执行的：单专家级回退 FP8 抑制长尾误差；层组级回退用于敏感层，防止 FP4 激活误差在多层叠加后放大破坏生成质量；整模型级回退作为兜底。触发条件写成可观测量的布尔组合，例如“专家偏差分位数超阈 且 该专家命中率高于下限”，避免对冷门专家误触发。回滚路径要预留在显存里——FP8 副本与 NVFP4 权重并存会吃掉一部分 4-bit 带来的显存红利，因此只对白名单层保留副本，其余按需从主机侧换入，代价是一次可预期的加载延迟而非全局重启。</p>\n<table class=\"mini\"><thead><tr><th>症状</th><th>首要观测量</th><th>处置</th></tr></thead><tbody><tr><td>长尾专家输出偏移</td><td>专家级余弦偏差、命中频次</td><td>单专家回退 FP8</td></tr><tr><td>带宽收益衰减</td><td>因子字节占比、有效位宽</td><td>增大 block 或回退 FP8</td></tr><tr><td>批抖动/尾延迟尖刺</td><td>每卡专家命中直方图、MMA 利用率</td><td>专家复制、路由均衡</td></tr><tr><td>OOM</td><td>峰值激活与因子元数据占用</td><td>降并发、收紧 block 元数据</td></tr></tbody></table>\n<h3 id=\"alg-nvfp4-moe-weights-sec-45\">四十五 · 同族量化的坐标系：三条轴决定选型</h3>\n<p>把 NVFP4 权重/激活量化放回它的同族里，选型不是“精度越高越好”的单变量问题，而是三条正交轴上的定位：<strong>缩放粒度</strong>（整张量 / 通道 / 每 16 或 32 元素的微缩放块）、<strong>位宽</strong>（FP16、FP8、FP4）、<strong>激活侧是否也量化</strong>（W-only 还是 W+A 联合）。NVFP4 的坐标是“微缩放块 + 4 bit + 激活可到 FP4”，它的邻居包括整张量统一量化（per-tensor FP8）、通道级 FP8（per-channel W8A8）、以及 W4A16 的纯权重量化。这三条轴共同决定两件事：局部动态范围保留得如何，以及 tcgen05 能否吃到原生 MMA 路径。</p>\n<p>缩放粒度直接对应误差上界。给定块内最大绝对值，缩放因子与每元素误差满足</p>\n<div class=\"formula\">$$s=\\frac{\\max|w_{\\text{block}}|}{\\text{FP4\\_MAX}},\\qquad \\epsilon\\le \\frac{s}{2}\\ \\text{每元素}$$</div>\n<p>块越小，$\\max|w_{\\text{block}}|$ 越贴近该块真实幅度，$s$ 越小，$\\epsilon$ 随之收紧；代价是元数据膨胀。整张量统一量化相当于把块放大到整张权重，$s$ 由全局最大值钉死，绝大多数元素的动态范围被浪费——这正是微缩放存在的理由，也是它与 per-tensor FP8 的分水岭。选型时先问：这张权重是否存在“少数大幅值元素压制多数小幅值元素”的分布？MoE 专家权重普遍如此，所以微缩放是默认项而非可选项。</p>\n<p>系统代价上，三条轴的组合直接改写解码的带宽账本。以专家权重驻留为例，FP16 下每专家权重占用量为基准 1，FP8 降到 1/2，NVFP4 降到 1/4；解码每 token 需读取被路由专家的全部权重，因此 HBM 读取字节数与位宽近似成正比，TPOT 的权重读取项随之压缩。但元数据不是免费的：每 16 元素一个 E8M0 因子意味着每 16 个 4-bit 值（8 字节）附带 1 字节缩放，元数据开销约 12.5%；若块缩到 8 元素，该比例翻倍，带宽收益被显著侵蚀。这就是“块太小反而更慢”的定量根源，也是选型时必须与 block 尺寸一起决策的原因。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-46\">四十六 · 决策表：按约束条件落位</h3>\n<p>下表把同族方案按“显存压力 / 带宽压力 / 精度余量 / 硬件档位”四类输入映射到推荐方案与适用条件。表中不写绝对数字，只写相对位宽与结构性判断，避免把定性结论伪装成实测。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>缩放粒度</th><th>位宽（W/A）</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody>\n<tr><td>per-tensor FP8</td><td>整张量</td><td>8 / 8</td><td>权重分布集中、显存与带宽均不紧张、追求最简部署</td><td>动态范围被全局最大值压制，长尾块误差大</td></tr>\n<tr><td>per-channel W8A8</td><td>通道</td><td>8 / 8</td><td>通道间幅度差异明显、激活分布稳定</td><td>通道缩放元数据中等，仍不足以容纳全部专家于单卡</td></tr>\n<tr><td>W4A16（纯权重量化）</td><td>块/组</td><td>4 / 16</td><td>激活量化风险高、显存受限但算力不缺</td><td>激活仍以 FP16 参与 MMA，算力密度不翻倍，带宽只省权重侧</td></tr>\n<tr><td>NVFP4 W4A8</td><td>每 16/32 元素</td><td>4 / 8</td><td>显存与带宽双受限的 MoE 解码，激活分布跨度大不宜压到 4 bit</td><td>激活侧 FP8 转换开销，缩放元数据读取</td></tr>\n<tr><td>NVFP4 W4A4</td><td>每 16/32 元素</td><td>4 / 4</td><td>Blackwell tcgen05 原生 FP4 MMA，激活分布温和、敏感层已回退</td><td>激活量化误差多层叠加，需逐层校验</td></tr>\n</tbody></table>\n<p>读表的关键是两列：位宽组合决定 tcgen05 能否走原生 FP4 MMA 路径，缩放粒度决定误差上界与元数据开销。W4A16 看似安全，但它放弃了激活侧的算力密度收益，只在“显存紧、算力富余”的错配场景成立；W4A4 是算力密度最高的落位，前提是激活分布经得起 4-bit 且敏感层已回退 FP8。W4A8 是折中位：权重吃满 4-bit 的显存与带宽收益，激活保留 FP8 的动态范围，适合激活跨层跨度大的模型。</p>\n<p>一个具体例子：某 MoE 解码服务在单卡上放不下全部专家，跨卡 All-to-All 成为尾延迟主因。若沿用 per-tensor FP8，专家权重仍占 FP16 的一半，单卡驻留专家数不足以消除跨卡流量；切到 NVFP4 W4A8 后权重降到 1/4，单卡可容纳更多专家，专家并行域缩小，All-to-All 频次下降。此处决策的驱动力是显存容量而非精度——精度只需“不低于可接受阈值”，而容量是硬约束。反过来，若某层激活存在极端离群值，W4A4 会把误差推过阈值，此时应保留 W4A8 而非强推 W4A4。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-47\">四十七 · 与 FP8 的对照：收益来自哪一段</h3>\n<p>与 FP8 相比，NVFP4 的收益可拆成两段：<strong>容量段</strong>与<strong>算力段</strong>。容量段来自位宽，专家权重显存降到 FP16 的 1/4（相对 FP8 再减半），直接改变“单卡能驻留多少专家”这一约束，进而改变并行拓扑与 All-to-All 规模。算力段来自 tcgen05 原生 FP4 MMA，算力密度翻倍，使分组 GEMM 的计算项不再是被带宽掩盖的次要项。两段收益的权重取决于负载处于 roofline 的哪一侧：解码阶段小 batch、权重读取主导，容量段收益占优；预填或大 batch 阶段计算占比上升，算力段收益显现。</p>\n<p>用 roofline 语言表述，单次分组 GEMM 的时间近似为</p>\n<div class=\"formula\">$$T\\approx\\max\\left(\\frac{B_w}{\\text{BW}_{\\text{HBM}}},\\ \\frac{F}{\\text{Peak}_{\\text{FP4}}}\\right)$$</div>\n<p>其中 $B_w$ 为该 token 路由专家需读取的权重字节（含缩放元数据），$F$ 为浮点运算量。FP8 下 $B_w$ 是 NVFP4 的两倍而 Peak 减半，故在带宽受限区 NVFP4 的 $T$ 约减半；在计算受限区，FP4 的 Peak 翻倍同样压缩 $T$。这就是“与 FP8 相比显存降 1/4、算力密度翻倍”在系统层面的落点，而不是两条孤立的产品参数。</p>\n<p>但 FP8 并未退场。敏感层回退 FP8 是 NVFP4 部署配方的固定组成：长尾专家样本少，4-bit 量化误差在其上累积，路由到这些专家的 token 输出会明显偏移；把这些层或这些专家保留在 FP8，等于用少量显存换稳定性。选型判断因此不是“全切 NVFP4”，而是“NVFP4 为主干 + FP8 为安全阀”，回退集合的大小由离线校准与在线漂移监测共同确定。回退比例越高，容量段收益越被稀释，这是选型时必须与精度验收一起量化的隐性成本。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-48\">四十八 · 与整张量统一量化的对照：局部动态范围的价值</h3>\n<p>整张量统一量化的失效模式很具体：一个离群大幅值元素把全局缩放因子抬高，其余元素被压进少数几个量化格点，有效位宽骤降。微缩放用每 16/32 元素共享的 E8M0 因子把这种“全局绑架”切断，块内元素各自在局部尺度上取格点。对 MoE 而言这尤其关键——不同专家的权重幅度天然不同，统一缩放会让小幅值专家几乎失去分辨率，而微缩放让每个专家、每个块自持尺度。</p>\n<p>代价侧同样具体。缩放因子元数据随 block 变小而增多，额外读取开销可能抵消 4-bit 权重带来的带宽节省；E8M0 的指数语义还要求因子落在 2 的幂上，块内动态范围超出可表示区间时只能牺牲精度而非溢出。选型判断因此落在 block 尺寸的折中点：16 元素块在元数据占比与局部分辨率之间取平衡，32 元素块元数据更省但对块内异质性更敏感。工程上应把 block 尺寸与量化校准一起冻结，而不是部署后再调。</p>\n<p>一个可操作的对照实验思路：在同一校准集上分别产出 per-tensor FP8、per-channel FP8、NVFP4（16 元素块）三份权重，用同一路由轨迹回放，比较长尾专家被命中时的输出偏移与端到端 TPOT。若 per-tensor FP8 在长尾专家上的偏移已超阈值，说明该模型必须走微缩放；若 per-channel FP8 已达标且显存不紧，则无需引入 FP4 的元数据开销。这一判断把“要不要 NVFP4”从偏好问题变成可测的容量—精度权衡。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-49\">四十九 · 与稀疏量化、投机解码的耦合边界</h3>\n<p>同族里还有两个容易被误配的邻居：硬件原生联合稀疏量化，以及 MoE 投机解码。前者把稀疏与低精度捆绑，后者改变每步验证的 token 数与专家命中分布。NVFP4 与它们的耦合有明确边界：稀疏量化改变的是“读多少权重”，NVFP4 改变的是“每个权重多少位”，两者在带宽账本上相乘而非相加，若稀疏结构未被 tcgen05 路径原生支持，压缩收益会在解压与重排中流失。选型时应先确认稀疏格式是否落在原生 MMA 的支持集合内，再决定是否叠加 FP4。</p>\n<p>与投机解码的耦合则体现在专家命中分布上。投机验证会一次性推入多个候选 token，路由命中的专家集合扩大，单步需读取的专家权重块增多；NVFP4 把每块字节压到 1/4，正好抵消这种扩张带来的带宽压力，但缩放元数据的读取次数也随命中专家数线性增长。若 block 过小导致元数据占比高，投机带来的批量命中反而放大元数据开销。这里的工程判断是：投机场景下优先选较大 block（32 元素）以压低元数据频次，把精度余量留给敏感层回退，而不是靠缩小 block 换分辨率。</p>\n<p>系统代价上，三条路径的叠加会改变 SLO 的瓶颈位置：稀疏降低有效字节、FP4 降低单位字节成本、投机提高每步并发 token 数，三者共同把瓶颈从 HBM 带宽推向元数据解析与反量化写回。此时优化重心应转向缩放因子的加载布局与累加器精度保持（FP32 累加不可省），而非继续压位宽。选型的终点不是“最省的格式”，而是“瓶颈迁移后仍不引入新瓶颈的组合”。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-50\">五十 · 适用条件的硬边界与验收口径</h3>\n<p>NVFP4 的适用边界是显存与带宽受限的 MoE 解码，硬件档位必须是支持 tcgen05 原生 FP4 MMA 的 Blackwell；离开这两个前提，收益结构不成立。规模上限受量化误差约束：长尾专家与敏感层需要回退 FP8，材料未给出具体精度下降数字，因此验收不能引用外部阈值，只能以自有校准集上的输出偏移与任务指标为准。选型表给出的是落位，不是保证——每一行都必须在目标负载上回放路由轨迹后才能签字。</p>\n<p>验收口径应包含三项：其一，容量项——单卡可驻留专家数是否足以缩小专家并行域、All-to-All 频次是否下降；其二，带宽项——每 token 权重读取字节（含元数据）相对 FP8 的实际降幅，若元数据侵蚀超过预期则回退 block 尺寸；其三，精度项——长尾专家命中时的输出偏移与敏感层回退后的端到端指标。三项中任一项不达标，就应退回相邻方案（W4A8 或 per-channel FP8），而不是在 NVFP4 内部继续调参。</p>\n<p>最后落在一条工程判断上：把“是否回退 FP8”做成按层、按专家的静态清单，并与量化校准产物一起版本化；在线只监测路由分布漂移，一旦长尾专家命中比例上升触发清单复核。这样 NVFP4 的容量收益是确定的，而 4-bit 误差累积被限制在已知的安全阀之内——选型的本质不是挑一个格式，而是把格式的失效模式关进可运维的笼子里。</p>\n\n<h3 id=\"alg-nvfp4-moe-weights-sec-51\">五十一 · 同族算法怎么选：NVFP4 的边界、失效条件与系统代价</h3>\n<p>NVFP4 不是孤立方案，它和 FP8 分块量化、整张量统一量化、MXFP4 同属一条谱系。选择的关键不在“谁更省”，而在“省下来的比特是否真的变成带宽”。同族算法的差别集中在缩放粒度与元数据开销：整张量统一量化只存一个标量缩放，元数据几乎为零，但局部动态范围被抹平，长尾专家与离群通道误差最大；MXFP4 与 NVFP4 都按 16 或 32 个元素共享 E8M0 缩放因子，保留局部动态范围，代价是每块附带一个指数字段。设块大小为 $B$、权重位宽为 $b$，有效位宽为</p>\n<div class=\"formula\">$$b_{\\text{eff}}=b+\\frac{8}{B}$$</div>\n<p>当 $B=16$ 时有效位宽为 4.5 bit，$B=32$ 时为 4.25 bit。这条式子直接给出决策的第一条判据：块越小，量化误差越小，但元数据读取越多。解码阶段每个 token 都要把选中专家的权重块从 HBM 拉进 SM，元数据与权重同路，block 太小时额外读取开销会抵消 4-bit 权重带来的带宽节省，这正是该方案的失效条件之一。工程上应把块大小与专家权重的行宽对齐，使一次加载同时覆盖权重与缩放因子，避免元数据触发独立的窄事务。</p>\n<p>第二条判据是误差是否可回退。4-bit 量化在长尾专家上误差累积，因为这些专家样本少、权重分布未被充分校准，路由到它们的 token 输出会明显偏移。此时不能靠调块大小解决，只能对量化敏感层回退到 FP8，形成混合精度专家池：多数专家 NVFP4，少数敏感层 FP8。系统代价是显存收益不再是整齐的 1/4，而是按回退比例打折；同时两套权重的加载路径并存，kernel 需要按层选择 MMA 变体，tcgen05 的 FP4 与 FP8 指令切换带来额外调度开销。适用条件是回退层占比可控，且回退后单卡仍能容纳目标专家数、缩小专家并行域。</p>\n<p>第三条判据是硬件档位与并行拓扑。NVFP4 依赖 tcgen05 原生 FP4 MMA，累加器保持 FP32；在没有该指令的档位上，4-bit 权重只能先反量化再走 FP8/FP16 MMA，带宽收益被反量化开销吃掉，此时应直接选 FP8。下表给出同族算法的适用条件对照。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>缩放粒度</th><th>适用条件</th><th>主要代价</th></tr></thead><tbody><tr><td>整张量统一量化</td><td>单标量</td><td>权重分布集中、无长尾专家</td><td>离群通道误差大</td></tr><tr><td>FP8 分块</td><td>块级</td><td>精度优先、显存尚可</td><td>显存仅降一半</td></tr><tr><td>MXFP4</td><td>32 元素 E8M0</td><td>通用 4-bit、元数据敏感</td><td>块内动态范围较粗</td></tr><tr><td>NVFP4</td><td>16/32 元素 E8M0</td><td>显存与带宽受限的 MoE 解码</td><td>长尾误差、元数据读取</td></tr></tbody></table>\n<p>落到具体例子：一个专家并行域内单卡需驻留的专家数受显存约束，权重压到 4 bit 后驻留数上升，跨卡 All-to-All 的专家流量随之下降，TPOT 的瓶颈从互联转向本地 HBM 读取；但若长尾专家回退 FP8 的比例偏高，驻留数回落，All-to-All 节省被抵消，此时应改回 FP8 并靠增大并行域换吞吐。决策顺序应是：先确认硬件支持 tcgen05 FP4 MMA，再确认回退比例与块对齐可行，最后才比较显存账。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 专家并行与All-to-All通信</td></tr><tr><td>解决什么</td><td>MoE 参数量巨大，权重显存占用使单卡放不下全部专家，HBM 带宽成为解码阶段读取专家的瓶颈，FP8 仍不够省。</td></tr><tr><td>一句话机制</td><td>用 MXFP4/NVFP4 微缩放格式把专家权重压到 4 bit，每 16 或 32 个元素共享一个 E8M0 缩放因…</td></tr><tr><td>代价与失效</td><td>4-bit 量化在长尾专家上误差累积，需要敏感层回退到 FP8；缩放因子带来额外元数据读取，block 太小时带宽收益被抵消</td></tr><tr><td>后继</td><td>预填解码分离部署</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-nvfp4-moe-weights · 共 8 个片段</p>\n";break;}}})();
